    \node[anchor=south west,inner sep=0] at (6,0) {\includegraphics[width=0.36\textwidth]{welding_example_3.png}}; 
    \end{tikzpicture}
    \caption{Left: Here we see the dynamical plane of the conformal mating $S$ of Example~\ref{011_ex}, with arrows indicating the action of $S$ on $\partial\cD$. Top Right: The two triangles on the left each map to $\Omega_1$ and $\Omega_2$ under appropriate Riemann maps, and the two triangles on the right are their copies. The induced action of $S$ on the boundaries of the four triangles is indicated. Bottom Right: The blender surface $\Sigma$, topologically speaking, is obtained by gluing the two cones via an orientation-reversing identification of the blue curves, as~shown.}
    \label{011_fig}
