    \label{111_fig}
    \end{figure}
    The group $\Gamma_{1,4}^2$ uniformizes a genus $0$ surface with two punctures and two order $2$ orbifold points. Therefore, unlike all the previous examples, the space $\text{Teich}(\Gamma_{1,4}^2)$ is non-trivial, in fact a $1-$dimensional complex manifold. Let $\mathcal{B}_2$ parametrize the quadratic Blaschke products with an attracting fixed point in $\mathbb{D}$, so $B\in\mathcal{B}_2$. Now note that for every parameter $t\in \text{Teich}(\Gamma_{1,4}^2)\times\mathcal{B}_2$, this specific construction would give us an elliptic curve $\Sigma_t$ (i.e., the blender surface), along with a degree $4$ elliptic function $\cR_t:\Sigma_t\rightarrow\widehat{\mathbb{C}}$ (i.e., the uniformizing meromorphic map)  with $6$ simple critical points and a double critical~point.
\end{example}

\begin{example}[\textbf{Genus $2$ blender surfaces from triply connected inversive domains}]\label{111''_ex}
    Let $R(z) = z^4 + \frac{4z^3}{\sqrt[3]{9}}$, and let $A_{\Gamma}$ be as in Example~\ref{111_ex}. One can check that $R$ is a critically fixed polynomial with $\text{Fix}(R) \supsetneq \text{Crit}(R) = \{-\sqrt[3]{3}, 0, \infty\}$. The critical points at $\infty, 0,$ and $-\sqrt[3]{3}$ have multiplicity $3$, $2$, and $1$, respectively. We let the conformal mating $S$ be the one that replaces the dynamics of $R$ on the basin of infinity with that of $A_{\Gamma_{5, 1}}^{\text{fBS}}$ (such that the fixed point $1$ of $A_{\Gamma_{5, 1}}^{\text{fBS}}$ is identified with the unique non-separating fixed point of $R$ on $\mathcal{J}(R)$); on the basin of the fixed point $0$ with that of $A_{\Gamma}$, and on the basin of the fixed point $-\sqrt[3]{3}$ with that of $A_{\Gamma_{1,3}}^{\text{BS}}$. Further, we conjugate $S$ via an appropriate  M\"obius map to ensure that it has a unique pole.
    \begin{figure}[h!]
    \captionsetup{width=0.98\linewidth}
    \begin{tikzpicture}
    \node[anchor=south west,inner sep=0] at (0,0) {\includegraphics[width=0.72\textwidth]{s_plane_example_6.png}}; 
    \end{tikzpicture}
    \caption{The domain of definition $\overline{\cD}$ of the conformal mating $S$ of Example~\ref{111''_ex} is the region bound by the cardioid, the triangle, and the quadrilateral.}
    \label{111''_fig}
    \end{figure}  

    The domain $\overline{\cD}$ is topologically a pair of pants (see Figure~\ref{111''_fig}), and the blender surface is obtained by gluing $\overline{\cD}$ to itself. Therefore, $\Sigma$ is a genus $2$ hyperelliptic Riemann surface, and the uniformizing meromorphic map $\cR:\Sigma\rightarrow\widehat{\mathbb{C}}$ has degree $5$ with a unique pole. 
\end{example}

\begin{example}[\textbf{Rigid Newton examples}]\label{111'''_ex}
    Consider the polynomial $P(z) = z^n-1$, $n\geq 3$, and let $R(z):= z - \frac{P(z)}{P'(z)}$ be the Newton map for the polynomial $P(z)$. Note that, 
    $$
    R(z) = z - \frac{z^n - 1}{nz^{n-1}} = z - \frac{z}{n} + \frac{1}{nz^{n-1}}, \hspace{2mm}\text{and}\hspace{2mm}R'(z)= \Bigg(\frac{n-1}{n}\Bigg)\cdot\Bigg(1-\frac{1}{z^n}\Bigg).
    $$
    As $R$ maps the point $0$ to the point $\infty$ with local degree $n-1$, we conclude that $\text{Crit}(R) = \{0\}\cup\{e^{\frac{2\pi ik}{n}}\}_{k\in\{1,\cdots, n\}}$, where $0$ is a critical point of multiplicity $n-2$, while all the $n$-th roots of unity are simple critical points of $R$. Let $S$ be the conformal mating of $R$, and $n$ copies of $A_{\Gamma_{3, 1}}^{\text{fBS}}$, one for each immediate basin of attraction of~$R$.

    The domain $\cD$ is a topological disk whose boundary is a wedge of $n$ Jordan curves. Since $\cD$ is connected, the associated blender surface $\Sigma$ is also connected (see Figure~\ref{111'''_fig}). The involution $\eta$ has $2g + 2$ fixed points, where $g$ denotes the genus of $\Sigma$. 
       \begin{figure}[h!]
    \captionsetup{width=0.98\linewidth}
    \begin{tikzpicture}
    \node[anchor=south west,inner sep=0] at (0,0) {\includegraphics[width=0.48\textwidth]{s_plane_example_7_1.png}}; 
    \node[anchor=south west,inner sep=0] at (6.2,0) {\includegraphics[width=0.48\textwidth]{s_plane_example_7_2.png}}; 
    \end{tikzpicture}
    \caption{Illustrated here are instances of the dynamical plane of $S$ from Example~\ref{111'''_ex}, for $n =3$ and $n=6$. Left: The three colored regions represent the immediate basins of the Newton map for the polynomial $z^3-1$, along with their pre-images. In each immediate basin, the original dynamics has been replaced by that of $A_{\Gamma_{3, 1}}^{\text{fBS}}$. Right: This image is based on the Newton map for the polynomial $z^6 - 1$, with modifications: in each of the six immediate basins, centered at the sixth roots of unity, the Newton dynamics has been surgically replaced by $A_{\Gamma_{3,1}}^{\text{fBS}}$. The conformal mating $S$ is defined in the exterior of the six red Jordan curves meeting at the central marked point; this corresponds to the point at infinity where all the immediate basins of the Newton map meet.}
    \label{111'''_fig}
    \end{figure}  

    We shall now attempt to arrive at a formula for $g$. Note that $A_{\Gamma_{3, 1}}^{\text{fBS}}$ has a fixed point on $l\cap C_{1,1}$ (see Section~\ref{fBS_subsec}). Under a conformal conjugation, this fixed point is carried to a fixed point of the map $S$. In addition, the map $R$ has a fixed point at $\infty$, and via a topological conjugation to the dynamical plane of $S$, the fixed point at $\infty$ maps to the intersection point of the $n$ Jordan curves forming $\partial\mathcal{D}$. We denote this point by $z_{\infty}$ (see the proof of Theorem~\ref{conf_mating_thm} for an explicit description of these conjugations). Thus, the map $S$ has a total of $n+1$ fixed points on $\partial\cD$: one arising from each copy of $A_{\Gamma_{3, 1}}^{\text{fBS}}$, and one corresponding to the point at $\infty$. 

    Note that the action of $S$ on $\partial^0\cD$ is topologically conjugate via the map $\cR$ to the involution $\eta$ on $\partial\mathfrak{D}\setminus\cR^{-1}(z_\infty)$ (see Equation~\ref{alg_char_eq}). Therefore, $\eta$ has exactly $n$ fixed points on $\partial\mathfrak{D}\setminus\cR^{-1}(z_\infty)$. Since all fixed points of $\eta$ lie on $\partial\mathfrak{D}$, it remains to study the action of $\eta$ on $\cR^{-1}(z_{\infty})\cap\partial\mathfrak{D}$. Observe that the quadratic map $\cQ:\Sigma\rightarrow\widecheck{\Sigma}$ maps $\cR^{-1}(z_{\infty})\cap\partial\mathfrak{D}$ to the point corresponding to $z_{\infty}$ in $\widecheck{\Sigma}$. Therefore, $\cR^{-1}(z_{\infty})\cap\partial\mathfrak{D}$ must either consist of a fixed point of $\eta$ or form a 2-cycle under $\eta$. Applying Proposition~\ref{genus_prop} and accounting for parity considerations, we arrive at the following conclusion:
    \begin{equation*}
        g = \begin{cases*}
            \frac{n}{2} - 1, & \text{if }$n$ is even,\\
            \frac{n - 1}{2}, & if $n$ is odd.
        \end{cases*}
    \end{equation*}
\end{example}

\begin{example}[\textbf{Genus two blender surfaces from doubly connected inversive domains}]\label{final_ex}
    Consider the critically fixed polynomial 
    $$
    R(z) = z^7 - \frac{7}{5}(\alpha^2 + \overline{\alpha}^2)z^5 + \frac{7}{3}|\alpha|^4z^3,
    $$ 
    where, $\alpha$ is a complex number in the first quadrant satisfying 
$$
15\alpha+6\alpha^7-14\alpha^5\overline{\alpha}^2=0.
$$    
    Since $R$ is symmetric about the real and imaginary axes; one can check that $\text{Fix}(R) \supsetneq \text{Crit}(R) = \{0, \alpha, \overline{\alpha}, -\alpha, -\overline{\alpha}, \infty\}$. The point $0$ is a critical point with multiplicity $2$, and all other finite critical points are simple. Let $B\in\mathcal{B}_2$ be as in Example~\ref{111_ex}. We let the conformal mating $S:\overline{\cD}\rightarrow\widehat{\C}$ be such that it replaces the dynamics of $R$ on the basin of the fixed point $0$ with that of $A_{\Gamma_{4,1}}^{\text{fBS}}$; on the basins of fixed points $\{\alpha, -\alpha, -\overline{\alpha}\}$ with that of $A_{\Gamma_{3,1}}^{\text{fBS}}$; and on the basin of the fixed point $\overline{\alpha}$ with that of $B$. 
    \begin{figure}[h!]
    \captionsetup{width=0.98\linewidth}
    \begin{tikzpicture}
    \node[anchor=south west,inner sep=0] at (0,0) {\includegraphics[width=0.8\textwidth]{s_plane_example_5.png}}; 
    \end{tikzpicture}
    \caption{Shown here is the dynamical plane of the conformal mating $S$ of Example~\ref{final_ex}. The two marked points correspond to the two repelling fixed points of the polynomial $R$.}
    \label{final_fig}
    \end{figure}  

    The domain $\cD$ is an annulus bound by the red and blue curves as shown in Figure~\ref{final_fig}. Let us denote the red curve by $\gamma_1$, and the blue curve by $\gamma_2$. Observe that welding two copies of $\cD$ along $\gamma_1$ via the map $S|_{\gamma_1}$ yields a genus $1$ surface with two boundary components; we call them $C_1$ and $C_2$ (cf. Figure~\ref{top_weld_surf_1_fig}). By construction, both $C_1$ and $C_2$ can be identified with $\gamma_2$, and the conformal involution $S|_{\gamma_2}$ induces an orientation-reversing analytic map $\widecheck{S}:C_1\rightarrow C_2$. Finally, gluing the two boundary components $C_1$ and $C_2$ via the map $\widecheck{S}$ would conclude the welding procedure by giving us a closed genus $2$ blender surface $\Sigma$. The uniformizing meromorphic map $\cR:\Sigma\rightarrow\widehat{\C}$ in this case has degree $8$ with a pole of order $7$ and a simple pole. Further, $\cR$ has a critical point of multiplicity $6$ (namely, the order $7$ pole),  a critical point of multiplicity $3$ (coming from $A_{\Gamma_{4,1}}^{\text{fBS}}$), three critical points of multiplicity $2$ each (coming from $A_{\Gamma_{3,1}}^{\text{fBS}}$), and three simple critical points (one from the Blaschke product $B$, and the other two from the singular points on $\partial\cD$). 
\end{example}

\begin{remark}
    The brief discussion above shows that a forward branch of the correspondence $\mathfrak{C}$ sends $z$ to $w$ if and only if either the conformal mating $S$ or one of its inverse branches sends $R(z)$ to $R(w)$. In other words, the meromorphic map $\cR$ lifts the dynamics of $S$ to the correspondence $\mathfrak{C}$.
\end{remark}

\begin{prop}\label{invariance_prop}\upshape 
The following statements hold for $i \in \{1, \cdots, l\}$.

\begin{enumerate}
    \item $\eta(\widetilde{\mathcal{W}_i}) = \widetilde{\mathcal{W}_i}$, and $\eta(\widetilde{\cK}) = \widetilde{\cK}$.
    \item Given a point $(z, w) \in \mathfrak{C}$, we have $z\in \widetilde{\mathcal{W}}_i$ (respectively, $z\in \widetilde{\cK}$) if and only if $w\in \widetilde{\mathcal{W}}_i$ (respectively, $w\in \widetilde{\cK}$).
\end{enumerate} 
\end{prop}

\begin{remark}\label{tesselation_rem}
    The tessellation of the unit disk $\mathbb{D}$ by the group $\Gamma_i$ can be transferred to the domain $\cT_i$. Define the rank zero tile as $\cT^0_i = \cT_i \setminus \cD$. The rank $m$ tiles are the connected components of the pre-image $S^{-m}(\cT^0_i)$. Every point in $\cT_i$ lies in a rank $m$ tile for some $m \geq 0$, and the action of $S$ maps each rank $m\geq 1$ tile to a rank $m-1$ tile. Therefore, all points in $\cT_i \cap \overline{\cD}$ eventually escape to the “hole” (i.e., the rank zero tile).

This dynamical tessellation can be lifted via the map $\cR|_{\widetilde{\cT}_i}$ to obtain a similar tiling structure in $\widetilde{\cT}_i$. A rank $m$ tile in $\widetilde{\cT}_i$ is defined as a connected component of the pre-image under $\cR|_{\widetilde{\cT}_i}$ of a rank $m$ tile in $\cT_i$. We denote the rank zero tile(s) in $\widetilde{\cT}_i$ by $\widetilde{\cT}_i^0$; these are the $p_i$ disjoint pre-images of $\cT^0_i$, one in each component of $\widetilde{\cT}_i$.
\end{remark}

\begin{remark}\label{esc_inv_rem}
The set $\widetilde{\cT_i}$ is invariant under $\eta$, which brings to attention a stark difference between the dynamics of the correspondence $\mathfrak{C}$ and the conformal mating $S$. While the points of $\cW_i$ eventually escape $\cD$ under the iterates of $S$; points in $\widetilde{\cW}_i$ ``eventually" map to $\widetilde{\cT_i}$, after which they remain  in $\widetilde{\cT_i}$ under $\eta$ as well as under suitable local deck transformations of $\cR$. In other words, by lifting the dynamics of the conformal mating $S$ to that of the correspondence $\mathfrak{C}$, we managed to suppress the escaping behavior exhibited by the former. Broadly speaking, we shall employ this philosophy to recover from $\mathfrak{C}$ the groups $\{\widehat{\Gamma}_i\}_{i=1}^l$. 
\end{remark}

\begin{theorem}\label{corr_recover_thm}
    The correspondence $\mathfrak{C}$ is a mating of the groups $\{\widehat{\Gamma}_i\}_{i=1}^l$, and the Blaschke products $\{B_j\}_{j=1}^r$, in the following sense.
    \begin{enumerate}[leftmargin=8mm]
        \item The action of $\mathfrak{C}_i$ on $\widetilde{\cT_i}$ is equivalent to the action of a group $\langle\eta, \tau_i\rangle$ of conformal automorphisms of $\widetilde{\cT_i}$, $i\in\{1,\cdots, l\}$. Moreover, the above group acts properly discontinuously, and the quotient orbifold $\widetilde{\cT_i}/\mathfrak{C}_i$ is biholomorphic to~$\mathbb{D}/\widehat{\Gamma}_i$.

        \item The correspondence $\mathfrak{C}$ has a forward branch (respectively, a backward branch) carrying $\widetilde{\cV}_j\cap \mathfrak{D}$ (respectively, $\widetilde{\cV}_j\setminus \overline{\mathfrak{D}}$) onto itself, and this branch is conformally conjugate to the Blaschke product $B_j$, $j\in\{1,\cdots,r\}$.
    \end{enumerate}
\end{theorem}

\begin{lem}\label{aut_corr_lem}
    The open set $\widetilde{\cT_i}$ admits a biholomorphism $\tau_i$ such that
    $$\tau^{n_ip_i}_i\equiv \text{id}, \hspace{2mm} and \hspace{2mm}\Big(\cR\big|_{\widetilde{\cT}_i}\Big)^{-1}\bigg(\Big(\cR\big|_{\widetilde{\cT}_i}\Big)(z)\bigg) = \{z, \tau_i(z), \cdots, \tau_i^{n_ip_i-1}(z)\} \hspace{2mm}\forall z\in \widetilde{\cT_i}.$$
\end{lem}

\begin{cor}\label{group_action_corr}
    The dynamics of $\mathfrak{C}_i$ on $\widetilde{\cT}_i$ is equivalent to the action of the group $\langle\eta, \tau_i\rangle$ of conformal automorphisms of $\widetilde{\cT}_i$.
\end{cor}

\begin{prop}\label{orbifold_isom_prop}
    The group $\langle\eta, \tau_i\rangle$ acts properly discontinuously on $\widetilde{\cT_i}$, and the quotient orbifold $\widetilde{\cT_i}/\langle\eta, \tau_i\rangle$ is biholomorphic to $\mathbb{D}/\widehat{\Gamma}_i$. 
\end{prop}

\begin{remark}\label{recover_rep_rem}
       The involution $\eta$ permutes the $p_i$ components of $\widetilde{\cT}_i$, as the set $\widetilde{\cT}_i$ is $\eta$-invariant. Let us denote this permutation by $\sigma_i$. Notably, $\sigma_i$ coincides with the permutation of the bi-infinite geodesics $\{\psi_{\rho_i}(C_{1,j})\}_{j=1}^{p_i}$, induced by the side-pairing transformations of $\Gamma_i$ on $\partial\psi_{\rho_i}(\Pi)$. By Lemma~\ref{aut_corr_lem}, the map $f_j$ in the proof of Proposition~\ref{orbifold_isom_prop} is of the form $\tau_i^{k_j}\circ\eta$, for some $1\leq k_j\leq p_i$, where $k_j$ is dictated by the permutation $\sigma_i$. Now note that by Equation~\ref{generators_eq}, the representation $(\widehat{\rho}_i:\widehat{\Gamma}_{n_i,p_i}\rightarrow\widehat{\Gamma}_i)\in \text{Teich}(\widehat{\Gamma}_{n_i,p_i})$ can be equivalently defined as follows:
       \begin{equation*}
           \widehat{\rho}_i(g_{1,j}):= \Phi_1^{-1}\circ\tau_i^{-(j-1)}\circ (\tau_i^{k_j}\circ\eta)\circ \tau_i^{j-1}\circ\Phi_1,\hspace{2mm}\text{and}\hspace{2mm}\widehat{\rho}_i(M_{\omega_i}):= \Phi_1^{-1}\circ\tau_i^{p_i}\circ\Phi_1 = M_{\omega_i}.
       \end{equation*}
       Therefore, the action of the multi-valued map $\mathfrak{C}_i$ on $\widetilde{\cT}_i$, helps us recover not only the group $\widehat{\Gamma}_i$, but also the representation $\widehat{\rho}_i$ in $\text{Teich}^{\omega_i}(\Gamma_{n_i,p_i})$.   
\end{remark}

\begin{prop}\label{recover_Blaschke_prop}
    There exists a forward branch (respectively, a backward branch) of $\mathfrak{C}$ carrying $\widetilde{\cV}_j\cap \mathfrak{D}$ (respectively, $\widetilde{\cV}_j\setminus \overline{\mathfrak{D}}$) onto itself, and this branch is conformally conjugate to the Blaschke product $B_j$.
\end{prop}

\begin{remark}
    Let $\mathcal{Z}:=\Sigma\setminus\bigcup_{i=1}^{l+r} \widetilde{\cW}_i$. Suppose that $\cR$ is injective on $\overline{\mathfrak{D}}$. Then, by replacing $\widetilde{\cV}_j\cap \mathfrak{D}$ (respectively, $\widetilde{\cV}_j\setminus \overline{\mathfrak{D}}$) with $\mathcal{Z}\cap \overline{\mathfrak{D}}$ (respectively, $\mathcal{Z}\setminus \mathfrak{D}$) in Proposition~\ref{recover_Blaschke_prop}, we obtain a topological conjugacy between $R$ and a forward branch (respectively, a backward branch) of the correspondence $\mathfrak{C}$, carrying $\mathcal{Z}\cap \overline{\mathfrak{D}}$ (respectively, $\mathcal{Z}\setminus \mathfrak{D}$) onto itself. Otherwise, one needs to pass to a nodal surface where the map $\cR$ descends to an injective map. This is precisely why a nodal surface was constructed in \cite[\S 5.2]{mj2023matings} to describe matings of Fuchsian groups with polynomials whose Julia sets are not Jordan curves.
\end{remark}

\begin{prop}\label{uniqueness_standard_mating_prop}
    Let $S:\overline{\cD}\rightarrow\widehat{\C}$ and $S':\overline{\cD'}\rightarrow\widehat{\C}$ be two standard conformal matings associated with the collections $\{\Gamma_i\}_{i=1}^l$ and $\{B_j\}_{j=1}^r$. Then there exists a M{\"o}bius map $M$ such that $S_1 = M\circ S_2\circ M^{-1}$.
\end{prop}

\begin{prop}\label{uniqeness_of_mero_prop}
    Suppose there exist $4$-tuples $(\Sigma_1, \cR_1, \mathfrak{D}_1, \eta_1)$, $(\Sigma_2, \cR_2, \mathfrak{D}_2, \eta_2)$ satisfying:
    \begin{enumerate}
        \item $\eta_i$ is an involution of $\Sigma_i$, with $\eta_i(\partial\mathfrak{D}_i) = \partial\mathfrak{D}_i$,
        \item $\cR_i|_{\mathfrak{D}_i}$ is injective,
        \item $\cR_i(\overline{\mathfrak{D}_i}) = \overline{\cD}$, and,
        \item $S|_{\overline{\cD}} = \cR_i\circ\eta_i\circ(\cR_i|_{\overline{\mathfrak{D}}_i})^{-1}$,
    \end{enumerate}
    for $i\in\{1, 2\}$. Then, there exists a biholomorphism $M: \Sigma_1 \rightarrow\Sigma_2$, such that $\eta_2\circ M = M\circ \eta_1$, $M(\mathfrak{D}_1) = \mathfrak{D}_2$, and $\cR_1 = \cR_2\circ M$.
\end{prop}

\begin{prop}\label{qc_lift_prop}
    There exists a quasiconformal map $\widetilde{\varphi}:\Sigma\rightarrow\Sigma'$, such that $\cR'\equiv \varphi\circ\cR\circ\widetilde{\varphi}^{-1}$ outside $\widetilde{\phi}\left(\eta\left(\left(\cR\vert_{\mathfrak{D}}\right)^{-1}\left(\bigcup_{j=1}^r\cV_j\right)\right)\right)$, and $\widetilde{\varphi}\circ\eta\circ\widetilde{\varphi}^{-1} = \eta'$.
\end{prop}

\begin{cor}\label{equiv_limit_sets_cor}
    The map $\widetilde{\varphi}$ conjugates the action of $\mathfrak{C}$ on $\Lambda(\mathfrak{C})$ to the action of $\mathfrak{C}'$ on $\Lambda(\mathfrak{C}')$.
\end{cor}

\begin{remark}\label{markings_preserved_rem}
    If the tuples $(\Sigma_1, \cR_1)$, $(\Sigma_2, \cR_2)$ were both associated with the conformal mating $S$, that is, they satisfied Conditions $(1)$-$(4)$ of Proposition~\ref{uniqeness_of_mero_prop}; then $M$ would take the marked points on $\Sigma_1$ to the marked points on $\Sigma_2$ bijectively, as an ordered set. 
\end{remark}

\begin{remark}
    Recall that in Example~\ref{111_ex}, each parameter $t \in \text{Teich}(\Gamma^2_{1,4})\times \mathcal{B}_2$ gives rise to a marked tuple $(\Sigma_t, \cR_t)$, where $\Sigma_t$ is an elliptic curve, and $\cR_t:\Sigma_t\rightarrow\widehat{\C}$ is a degree $4$ elliptic function with $6$ simple critical points and a double critical point. Therefore, by Theorem~\ref{hurwitz_thm_intro}, we get an injective map from $\text{Teich}(\Gamma^2_{1,4})\times \mathcal{B}_2$ into the Hurwitz space $\mathcal{H}_{1, 4, 11}^{\text{hyp}}$.
\end{remark}

