    \label{fac_BS_modular_fig}
\end{figure}

Define $\mathcal{U}_{\Gamma_{n,p}}$ to be the projection of $\mathbb{D}\backslash \Pi$ under $z\mapsto z^n$, then $A_{\Gamma_{n, p}}^{\text{fBS}}$ is defined on $\overline{\mathcal{U}}_{\Gamma_{n,p}}$. Note that $\mathbb{S}^1 \subset \partial \mathcal{U}_{\Gamma_{n,p}}$. By \cite[Proposition~2.5]{mj2023matings}, the map $A_{\Gamma_{n, p}}^{\text{fBS}}: \mathbb{S}^1 \rightarrow \mathbb{S}^1$ is an orientation-preserving expansive covering map of degree $np-1$ . In particular, it is topologically conjugate to the map $z^{np-1}\big|_{\mathbb{S}^1}$. Let us denote by $h:\mathbb{S}^1 \rightarrow \mathbb{S}^1$ the homeomorphism  that conjugates $z^{np-1}$ to $A_{\Gamma_{n, p}}^{\text{fBS}}$, normalized so that,
\begin{itemize}[leftmargin=6mm]
    \item in Case I, the fixed point $1$ of $z^{np-1}$ goes to the fixed point $1$ of $A_{\Gamma_{n, p}}^{\text{fBS}}$, and
    \item in Case II, the fixed point $1$ of $z^{np-1}$ goes to the projection under $z\mapsto z^n$ of the endpoint of $\widetilde{l}$ in the half-plane determined by $C_{1,1}$ (contained in $\overline{\D}\setminus\Pi$).
\end{itemize}

We denote by $\text{Teich}(\Gamma_{n, p})$ the Teichm{\"u}ller space of $\Gamma_{n,p}$, where the quasiconformal conjugations $\psi_\rho$ are normalized as in Section~\ref{cBS_subsec}.
Its subset $\text{Teich}^{\omega}(\Gamma_{n, p})$ is defined as the collection of $(\rho: \Gamma_{n, p}\rightarrow \Gamma) \in \text{Teich}(\Gamma_{n, p})$ such that $\psi_\rho$ commutes with $M_{\omega}$. Define
$$
\widehat{\Gamma} := \langle\Gamma, M_{\omega}\rangle.
$$
By associating to each $(\rho:\Gamma_{n,p}\to\Gamma) \in \text{Teich}^{\omega}(\Gamma_{n, p})$ the representation $(\widehat{\rho}:\widehat{\Gamma}_{n,p}\to\widehat{\Gamma})\in \text{Teich}(\widehat{\Gamma}_{n,p})$, where
$$
\widehat{\rho}\big|_{\Gamma_{n,p}} \equiv \rho\big|_{\Gamma_{n,p}} \hspace{2mm}\text{and}\hspace{2mm} \widehat{\rho}(M_{\omega}) = M_{\omega},
$$
we see that $\text{Teich}(\widehat{\Gamma}_{n,p})$ can be identified with $\text{Teich}^{\omega}(\Gamma_{n, p})$.
