\begin{definition}
    For a given representation $(\rho:\Gamma_{n, p} \rightarrow \Gamma) \in \text{Teich}^{\omega}(\Gamma_{n, p})$, the \textbf{factor Bowen-Series map} $A_{\Gamma}^{\text{fBS}}: \overline{\mathcal{U}}_{\Gamma} \rightarrow \overline{\mathbb{D}}$, associated with the representation $\rho$, is given by $\psi_{\rho}\circ A_{\Gamma_{n, p}}^{\text{fBS}}\circ \psi_{\rho}^{-1}$, where $\mathcal{U}_{\Gamma}:= \psi_{\rho}\big(\mathcal{U}_{\Gamma_{n, p}}\big)$. 
\end{definition}

Note that for each $\rho \in \text{Teich}^{\omega}(\Gamma_{n, p})$, the associated Bowen-Series map $A_{\Gamma}^{\text{BS}}$ commutes with $M_{\omega}$, hence the quasiconformal conjugacy $\psi_{\rho}$ between $\Gamma_{n, p}$ and $\Gamma$ descends to a quasi-conformal conjugacy $\widehat{\psi}_{\rho}$ between $A_{\Gamma_{n, p}}^{\text{fBS}}$ and $A_{\Gamma}^{\text{fBS}}$. As the space $\text{Teich}^{\omega}(\Gamma_{n, p})$ can be identified with $\text{Teich}(\widehat{\Gamma}_{n,p})$, the collection of the factor Bowen-Series maps $A_\Gamma^{\text{fBS}}$ is parametrized by the Teichm{\"u}ller space of the quotient $\mathbb{D}/\widehat{\Gamma}_{n,p}~\in~\mathcal{F}$. 

Define $h_\Gamma:=\widehat{\psi}_\rho\circ h:\mathbb{S}^1\to\mathbb{S}^1$, the normalized map that establishes a topological conjugacy between $z^{np-1}$ and $A_{\Gamma}^{\text{fBS}}$. This conjugacy will play an important role in the surgery construction of Section~\ref{conf_mating_sec}.

\begin{remark}
     Notice that the side-pairing constructions in Sections~\ref{cBS_subsec} and~\ref{fBS_subsec} are identical when $n=1$. In this case, we use the convention that $\widehat{\Gamma}_{n,p} = \Gamma_{n,p}$, $\widehat{\Gamma}=\Gamma$, $\widehat{\Pi} = \Pi$, $\widehat{\rho}=\rho$, and $\text{Teich}^{\omega}(\Gamma_{n, p})=\text{Teich}(\Gamma_{n, p})$.
\end{remark}

\begin{remark}
     The key difference between the constructions in Sections~\ref{cBS_subsec} and~\ref{fBS_subsec} is the emergence of an order $n\geq 3$ orbifold point in the quotient surface of the latter. This particular feature is accommodated for by 
    {\upshape
    \begin{enumerate}[leftmargin=8mm,label=\alph*)]
        \item taking $n$ sectors of angle $\frac{2\pi}{n}$ each, and fitting geodesics appearing in Section~\ref{cBS_subsec} in every sector, and
        \item preserving the identifications among the geodesics in one sector, and transferring the identifications to the geodesics in the other sectors via maps $M_{\omega}^{r-1}$, for $r\in\{1,\cdots, n\}$. (See Figure~\ref{remark_2.5_fig}.)
    \end{enumerate}
    }
    Therefore, as the groups in Section~\ref{cBS_subsec} are associated with orbifolds that have any number of punctures and at most $2$ order two orbifold points; the groups in Section~\ref{fBS_subsec} are associated with orbifolds that admit an arbitrary number of punctures, at most $2$ order two orbifold points, and exactly $1$ order $n\geq 3$ orbifold point. The maps in Section~\ref{fBS_subsec} were first introduced in \cite{mj2023matings} to present an alternate way of combining modular groups with quadratic maps, thus bringing to attention a different perspective on the Bullett-Penrose family of correspondences \cite{bullett1994mating}.
\end{remark}

\begin{lem}\label{david_ext_lem}
The circle homeomorphism $h_\Gamma:\mathbb{S}^1\rightarrow \mathbb{S}^1$ continuously extends to a David homeomorphism $h_\Gamma$ of $\mathbb{D}$. 

More generally, if $B$ is a degree $d$ Blaschke product with an attracting fixed point in $\D$, then there exists a circle homeomorphism $h_{B,\Gamma}$ that conjugates $B$ to $A_\Gamma^{\text{fBS}}$ (respectively, $A_{\Gamma}^{\text{BS}}$), and extends continuously to a David homeomorphism of $\D$.
\end{lem}
\begin{proof}
The first statement is the content of \cite[Lemma~3.4]{mj2023matings}, and \cite[Proposition~2.7]{mj2023combining}. For the second statement, let $\theta_{B}: \mathbb{S}^1\rightarrow\mathbb{S}^1$ be a quasisymmetric conjugacy from $B$ to $z^d$. The map $\theta_{B}$ can be extended continuously as a quasiconformal homeomorphism of $\mathbb{D}$. And by the first statement, the map $h_{\Gamma}$ can be extended continuously to $\mathbb{D}$ as a David homeomorphism. Using the same notation for the extensions of $\theta_B$ and  $h_{\Gamma}$ to the unit disk $\mathbb{D}$, define $h_{B, \Gamma}:= h_{\Gamma}\circ \theta_{B}$. By \cite[Proposition~2.5 (iv)]{lyubich2020david}, $h_{B, \Gamma}$ is a David homeomorphism of $\mathbb{D}$.
\end{proof}


  Now define the following topological dynamical system:
    \begin{equation*}
        \widetilde{S} = \begin{cases*}
      R & on\ $\ \widehat{\mathbb{C}}\backslash \displaystyle\bigsqcup_{i=1}^{l+r}U_i$ \\
      \zeta_i^{-1}\circ A_{\Gamma_i}\circ \zeta_i  & on $\ \zeta_i^{-1}(\overline{\cU}_{\Gamma_i})\subseteq \overline{U_i},\ i\in\{1,\cdots,l\}$\\
      \zeta_{l+j}^{-1}\circ B_{j}\circ \zeta_{l+j} & on $\ \zeta_{l+j}^{-1}(\overline{\D}_{l+j})=\overline{U_{l+j}},\ j\in\{1,\cdots,r\}$.
    \end{cases*}
    \end{equation*}
    To upgrade $\widetilde{S}$ to a conformal dynamical system, we construct an invariant Beltrami coefficient. Let $\mu_i$ be the pullback of the standard complex structure on $\mathbb{D}_i$ under the map $\zeta_i$, $i\in\{1,\cdots,l+r\}$. Use the dynamics of $R$ to spread $\mu_i$ on all pre-images of $U_i$, and everywhere else put the standard complex structure. It is now evident that the Beltrami coefficient $\mu$ so defined is $\widetilde{S}$ invariant. By applying arguments in \cite[Lemma~7.1]{lyubich2020david} (as is) one can prove that $\mu$ is a David coefficient. Hence, by David Integrability Theorem \cite[Theorem~20.6.2]{astala2008elliptic}, there exists a David homeomorphism 
    $$
    H:\widehat{\mathbb{C}}\rightarrow \widehat{\mathbb{C}}
    $$
    that straightens the coefficient $\mu$. Set, 
    $$
    S:= H\circ \widetilde{S}\circ H^{-1}
    $$
    As $\partial U_i$ is $W^{1, 1}$ removable, by \cite[Theorem~2.7]{lyubich2020david}, the set $H(\partial U_i)$ is conformally removable for $i\in \{1, 2, \cdots, l+r\}$. It is therefore sufficient to check that $S$ is conformal on $\displaystyle\text{Dom}(S)\backslash \bigcup_{i=1}^{l+r} H(\partial U_i)$. 


    The maps $\zeta_i$ and $H$ are David homeomorphisms on $U_i$ straightening $\mu$, therefore by \cite[Theorem~20.4.19]{astala2008elliptic}, the map $\zeta_i\circ H^{-1}$ is conformal on $H(U_i)\cap \text{Dom}(S)$, $i\in \{1, 2, \cdots, l+r\}$. This implies that $S$ is holomorphic on $H(U_i)\cap\mathrm{Dom}(S)$, $i\in \{1, 2, \cdots, l+r\}$. Further, the maps $H\circ R$ and $H$ restricted to $\displaystyle\widehat{\mathbb{C}}\backslash \bigsqcup_{i=1}^{l+r} U_i$ again straighten $\mu$. Therefore, the map $S$ is holomorphic on $\displaystyle H\big(\widehat{\mathbb{C}}\backslash \bigsqcup_{i=1}^{l+r} U_i\big)$ as well. This concludes the proof of the fact that $S$ is holomorphic in the interior of its domain of definition. Evidently,
    \begin{enumerate}[leftmargin=6mm]
        \item $\mathfrak{X}_R:= H$ is a conformal conjugacy from $R$ to $S$ outside the grand orbit of~$\displaystyle\bigsqcup_{i=1}^{l+r} U_i$,

        \item $\mathfrak{X}_i := H\circ\zeta_i^{-1}$ is a conformal conjugacy from $A_{\Gamma_i}$ to $S$ on $\D_i$, $i\in\{1,\cdots,l\}$, and

         \item $\mathfrak{X}_{l+j}:= H\circ\zeta_{l+j}^{-1}$ is a conformal conjugacy from $B_{j}$ to $S$ on $\D_{l+j}$, for indices $j\in\{1,\cdots,r\}$.
    \end{enumerate}
    Thus, $S$ is the desired conformal mating of the dynamical systems under consideration.
\end{proof}

\begin{remark}\label{invariant_subset_rem}\upshape
Define $\cT_i:=H(U_i)$, $i\in\{1,\cdots,l\}$, and $\mathcal{V}_j:=H(U_{l+j})$, $j\in\{1,\cdots,r\}$. Let $\mathcal{W}_i$ stand for the grand orbit of $\cT_i$ under $S$, for $i\in\{1,\cdots,l\}$, and the grand orbit of $\mathcal{V}_{i-l}$ under $S$, for $i\in\{l+1,\cdots,l+r\}$. Finally, let $\cK := \widehat{\mathbb{C}}\backslash \bigcup_{i=1}^{l} \mathcal{W}_i$.

    The tessellation induced by the group dynamics of $\Gamma_i$ on $\mathbb{D}$ can be transferred via appropriate conjugacies to $\cT_i \subset \mathcal{W}_i$, $i\in\{1,\cdots,l\}$. The totally invariant sets $\displaystyle\bigcup_{i = 1}^{l} \mathcal{W}_i$ and $\cK$, which are the \emph{escaping} and \emph{non-escaping} sets of $S$ (respectively), partition the Riemann sphere. This partition will be of importance in Section~\ref{correspondences_sec}.
\end{remark}

\subsection{Weak B-involution}\label{weak_b_inv_def_subsec}

\begin{definition}\label{weak_b_inv_def}
    Let $\{\Omega_1, \cdots, \Omega_k\}$ be disjoint finitely connected proper subdomains of $\widehat{\mathbb{C}}$ with $\text{int}(\overline{\Omega_i}) = \Omega_i$ for $i\in \{1, 2, \cdots, k\}$. Set $\mathcal{D}:= \bigsqcup_{i=1}^k \Omega_i$. Further, let $X\subset \partial \cD$ be a finite set such that $\partial^0\cD := \partial\cD\backslash X$ is a finite union of disjoint non-singular real analytic curves. For notational convenience, let us also set $\partial^0 \Omega_i:= \partial^0\cD \cap \overline{\Omega}_i$. We call $\cD$ an \textbf{inversive multi-domain} if there exists a continuous map $S: \overline{\cD} \rightarrow \widehat{\C}$ satisfying the following:
    \begin{enumerate}
        \item\label{cond_mero} $S$ is meromorphic on $\cD$,
        \item\label{cond_inv} $S:(\partial\cD,X)\to (\partial\cD,X)$ is an involution, and
        \item\label{cond_or} $S: \partial^0 \cD \rightarrow \partial^0 \cD$ is orientation-reversing.
    \end{enumerate}
    The map $S$ is called a \textbf{weak B-involution} of the inversive multi-domain $\cD$. If $k= 1$, the domain $\cD$ is called an \textbf{inversive domain}. Set $T:= \widehat{\C}\backslash \cD$ and $T^{0}:= T\backslash X$.
\end{definition}

\begin{remark}\label{B_involution_rem}
\upshape
Definition~\ref{weak_b_inv_def} generalizes the class of maps called \emph{B-involutions}, which were introduced and studied in \cite[\S 14]{luo2024general}.
The key difference between B-involutions a la \cite{luo2024general} and our notion of weak B-involutions lies in the subtle fact that Definition~\ref{weak_b_inv_def} only requires $S$ to be orientation-reversing on the desingularized boundary $\partial^0\cD$ of its domain of definition; while a B-involution in the sense of \cite{luo2024general}
is also required to reverse the cyclic order of the local real-analytic arcs of $\partial^0\cD$ meeting at a singular point in $X$. Further, we drop the requirement that $S$ carries the boundary of some component $\Omega_i$ to that of some component $\Omega_{i'}$, allowing for richer boundary behavior. Finally, we relax the condition that each $\Omega_i$ is simply connected. 

All of the above relaxations are dictated by our general combination procedure for multiple Fuchsian groups with multiple Blaschke products (see Section~\ref{examples_sec}).
\end{remark}

\begin{remark}
    A conformal mating $S$ in the sense of Theorem~\ref{conf_mating_thm} is meromorphic on the interior $\cD$ of its domain of definition. Note that by Remark~\hyperref[BSmap_domain_rem]{\ref*{BSmap_domain_rem}~{\upshape(ii)}}, a (factor) Bowen-Series map is an orientation-reversing involution on (the closure of) its inner boundary, fixing the set of ideal vertices. And since $S$ is conjugate to the dynamics of (factor) Bowen-Series maps on appropriate regions, $S$ satisfies Conditions~\eqref{cond_inv} and~\eqref{cond_or} in Definition~\ref{weak_b_inv_def}. Therefore, such maps readily show up as instances of weak B-involutions on inversive multi-domains. 
\end{remark}

\subsection{Characterization of weak B-involutions}\label{char_weak_b_inv_subsec}
We shall now establish the algebraicity of general weak $B$-involutions.  

\begin{theorem}\label{alg_weak_b_inv_thm}
    Let $\cD$ be an inversive multi-domain with a weak B-involution $S:\overline{\cD} \rightarrow \widehat{\C}$. Then there exist
    \begin{itemize}
        \item $\Sigma$, a finite union of compact Riemann surfaces,
        \item $\mathfrak{D}\subset\Sigma$, a disjoint union of finitely connected domains with a piecewise non-singular real-analytic boundary,
        \item a conformal involution $\eta: \Sigma\rightarrow\Sigma$ with $\eta(\mathfrak{D})=\Sigma\backslash\overline{\mathfrak{D}}$, and
        \item a holomorphic map $\mathcal{R}:\Sigma \rightarrow \widehat{\C}$ that carries $\mathfrak{D}$ conformally onto $\cD$,        
    \end{itemize}
    such that 
    \begin{equation}\label{alg_char_eq}
        S\big|_{\cD} \equiv \mathcal{R}\circ \eta\circ \big(\mathcal{R}\big|_{\mathfrak{D}}\big)^{-1}.
    \end{equation}
\end{theorem}

\begin{remark}\upshape

1) For the restricted class of weak B-involutions considered in \cite{luo2024general}, an analogous algebraic description was given in \cite[Theorem~14.5]{luo2024general}, where the surface $\Sigma$ turned out to be a disjoint union of Riemann spheres. On the other hand, in our relaxed setting, the surface $\Sigma$ can have arbitrary genus even if $\cD$ is connected and simply connected (see Section~\ref{examples_sec}).

2) Let us also point out that an analogous construction exists in the antiholomorphic setting; namely, the Schwarz reflection map of a quadrature domain (an anti-meromorphic map of a domain that extends as the identity map on the boundary) admits an algebraic description in terms of a reflection map and a meromorphic function on a compact Riemann surface \cite{Gus83}. However, the antiholomorphic setting is somewhat restricted: for a Schwarz reflection map on a simply connected quadrature domain, the associated meromorphic function is always defined on $\widehat{\C}$.
\end{remark}


\begin{proof}
We shall prove this statement in steps (cf. \cite[Lemma~14.3]{luo2024general}).
\medskip

\noindent\textbf{Step 1: Welding a Riemann Surface.}    
    Observe that $S:\partial \cD\rightarrow \partial \cD$ is a homeomorphism that is orientation-reversing on $\partial^0\cD$. Further, $S$ is meromorphic on $\cD$ and extends continuously to $\partial^0\cD$ preserving $\partial^0\cD$ . Hence, by Schwarz reflection principle $S$ extends to a holomorphic map in a neighborhood of $\partial^0 \cD$. As $S^{\circ 2}\big|_{\partial^0\cD} = \mathrm{id}$, by the Identity Theorem, $S$ is a conformal involution in a neighborhood of $\partial^0 \cD$. We now weld $\cD \cup \partial^0 \cD$ with a copy of itself via the conformal involution $S: \partial^0 \cD\rightarrow \partial^0 \cD$ (cf. \cite[Chapter~2, Page~117]{ahlfors2015riemann}). The resulting object is a finite union of bordered Riemann surfaces of finite genus (see Figure~\ref{top_weld_surf_1_fig}). We denote this surface by $\Sigma^0$.
\begin{figure}
\captionsetup{width=0.98\linewidth}
    \centering
    \includegraphics[width=0.88\linewidth]{topology_welded_surface.png}
    \caption{A domain whose boundary is a wedge of three circles is uniformized by the disk (above). The single meeting point of the three circles opens up to three points drawn in black. The disks are then welded via the lift of the conformal involution near the boundary of the original domain. Finally, the topology of the surface one gets from such a welding procedure is illustrated.}
    \label{top_weld_surf_1_fig}
\end{figure}
\medskip

\noindent\textbf{Step 2: Conformal Involution $\eta$ on $\Sigma^0$.}   
The welding of $\cD\cup \partial^0\cD$ with a copy of itself to get $\Sigma^0$ comes with maps $\psi_1$, $\psi_2: \cD\cup \partial^0\cD \rightarrow \Sigma^0$, such that, 
\begin{itemize}
    \item $\psi_i$ is conformal in $\cD$ and a homeomorphism on $\cD\cup \partial^0 \cD$, $i\in\{1,2\}$, 
    \item $\psi_1(\cD)\cap \psi_2(\cD) = \emptyset$,
    \item $\psi_1(\partial^0 \cD) = \psi_2(\partial^0 \cD)$ is a union of non-singular real analytic curves,
    \item $\psi_2^{-1}\circ\psi_1 \equiv S$ on $\partial^0\cD$, and
    \item $\Sigma^0 = \psi_1(\cD\cup \partial^0\cD) \cup \psi_2 (\cD)$.
\end{itemize}
\vspace{1mm}
Define $\eta: \Sigma^0\rightarrow \Sigma^0$ as
\begin{equation*}
    \eta:= \begin{cases*}
      \psi_2\circ \psi_1^{-1} & on $\psi_1(\cD\cup \partial^0\cD)$ \\
      \psi_1\circ \psi_2^{-1}        & on $\psi_2(\cD)$.
    \end{cases*}
\end{equation*}
Since $\psi_1 = \psi_2\circ S$ on $\partial^0\cD$ and $S^{\circ 2} \equiv \mathrm{id}$ on $\partial^0\cD$, we have that $\eta$ is a conformal involution on $\Sigma^0$.
\medskip

\noindent\textbf{Step 3: $\Sigma^0$ is a finite type surface.}
Define the meromorphic map, 
$$\mathcal{R}: \Sigma^0\backslash \psi_2((S\vert_{\cD})^{-1}(X)) \rightarrow \widehat{\mathbb{C}}\backslash X$$
as follows, 
\begin{equation*}
    \mathcal{R}:= \begin{cases*}
        \psi_1^{-1} & on $\psi_1(\cD\cup \partial^0\cD)$ \\
        S\circ \psi_1^{-1}\circ \eta = S\circ \psi_2^{-1} & on $\psi_2(\cD\backslash (S\vert_\cD)^{-1}(X))$
    \end{cases*}
\end{equation*}
We first claim that $\mathcal{R}$ is a proper mapping. Indeed, $\psi_1$, $\psi_2$ being homeomorphisms are proper maps. As $S$ is continuous on $\mathcal{D}$, for any sequence of points $\{x_n\}_n$ converging to $\psi_2((S\vert_{\cD})^{-1}(X))$, the image sequence $\mathcal{R}(x_n)$ converges to $X$. Now suppose that the sequence $\{x_n\}_n$ escapes to a boundary component of $\Sigma^0$, then $\psi_2^{-1}(x_n)$ converges to a point in $X$. Since $S\vert_{\overline{\cD}}$ is continuous carrying $X$ to itself, it follows that $\mathcal{R}(x_n) = S(\psi_2^{-1}(x_n))$ converges to a point in $S(X) = X$.
This shows that $\mathcal{R}$ is a proper holomorphic map. 

Suppose that $\text{deg}(\mathcal{R}) = \infty$. Then, for points $z\in \widehat{\mathbb{C}}\backslash X$, the pre-image $\mathcal{R}^{-1}(z)$ is an infinite set in $\Sigma^0\backslash \psi_2((S\vert_{\cD})^{-1}(X))$. By the Identity Theorem, as $\mathcal{R}$ is non-constant, $\mathcal{R}^{-1}(z)$ accumulates either on $\psi_2((S\vert_{\cD})^{-1}(X))$ or on $\partial \Sigma^0$ which violates the fact that $\mathcal{R}$ is proper. Hence, $\mathcal{R}$ is a finite degree branched cover from $\Sigma^0\backslash \psi_2((S\vert_{\cD})^{-1}(X))$ to $\widehat{\mathbb{C}}\backslash X$. 

We make further punctures in $\widehat{\mathbb{C}}\backslash X$ (if necessary) to ensure that $\mathcal{R}$ is a covering map over the resulting punctured sphere. We then triangulate this punctured sphere, and lift the triangulation via the covering map $\mathcal{R}$ to a triangulation upstairs. This would yield a finite triangulation on the surface $\Sigma^0\backslash \psi_2((S\vert_{\cD})^{-1}(X))$, with finitely many points removed. This would force $\Sigma^0\backslash \psi_2((S\vert_{\cD})^{-1}(X))$ to be a surface of finite type. This implies that $(S\vert_{\cD})^{-1}(X)$ is a finite set, and hence $\Sigma^0$ is a finite union of punctured surfaces of finite genus. We will denote the compactification of $\Sigma^0$ (which is obtained by filling in the finitely many punctures) by $\Sigma$.
\medskip

\noindent\textbf{Step 4: Explicit Algebraic Description of $S$.}
By the Riemann Removability Theorem, the maps $\mathcal{R}$ and $\eta$ extend holomorphically to the compact Riemann surface $\Sigma$. We remark that if $\Sigma$ is the Riemann sphere, one can after a change of coordinates assume that $\eta(z)= 1/z$. Set $\mathfrak{D} = \psi_1(\cD)$. Then from the definition of $\mathcal{R}$ one obtains, 
$$
\mathcal{R}\Big|_{\Sigma\backslash \overline{\mathfrak{D}}} \equiv S\Big|_{\cD}\circ \mathcal{R}\Big|_{\mathfrak{D}}\circ \eta\Big|_{\Sigma\backslash \overline{\mathfrak{D}}}
$$
which yields, 
$$
S\Big|_{\cD} = \mathcal{R}\circ \eta\circ \Big(\mathcal{R}\Big|_{\mathfrak{D}}\Big)^{-1}.
$$
The facts that $\eta(\mathfrak{D})=\Sigma\backslash\overline{\mathfrak{D}}$ and
 $\mathcal{R}:\mathfrak{D}\to\cD$ is a conformal isomorphism follow directly from the construction. 
\end{proof}


\begin{cor}\label{b_inv_fin_deg_cor}
With the setup as in Theorem~\ref{alg_weak_b_inv_thm}, we have that $S: S^{-1}(\cD) \rightarrow \cD$ is a branched covering of degree $d_{\mathcal{R}}-1$, and  $S: S^{-1}(\text{int}(T)) \rightarrow \text{int}(T)$ is a branched covering of degree $d_{\mathcal{R}}$, where $d_{\mathcal{R}}$ is the degree of the meromorphic map $\mathcal{R}:\Sigma\to\widehat{\C}$.
\end{cor}
\begin{proof}
The statements follow from the relation $S\Big|_{\cD} = \mathcal{R}\circ \eta\circ \Big(\mathcal{R}\Big|_{\mathfrak{D}}\Big)^{-1}$. 
\end{proof}

\begin{cor}\label{crit_points_cor}
    Let the weak B-involution $S:\overline{\cD}\to\widehat{\C}$ be a conformal mating of a sub-hyperbolic map $R$, the Blaschke products $\{B_j\}_{j=1}^r$ and the (factor) Bowen-Series maps $\{A_{\Gamma_i}\}_{i=1}^l$ associated with the representations $\rho:\Gamma_{n_i, p_i}\rightarrow \Gamma_i$ (constructed in Theorem~\ref{conf_mating_thm}). Let $\cT_i$ be as in Remark~\ref{invariant_subset_rem}. 
        For indices $i \in \{1, 2, \cdots, l\}$ with $n_i\geq 3$, the map $\cR$ has a critical value in $\cT_i$. Moreover, that critical value admits at least $p_i$ distinct pre-images under $\mathcal{R}$, each with multiplicity $n_i-1$.
\end{cor}
\begin{proof}
    Note that for indices $i \in \{1, 2, \cdots, l\}$ with $n_i\geq 3$, the factor Bowen-Series map $A_{\Gamma_{n_i, p_i}}$  has a unique critical value in $\mathbb{D}$ at $0$ with $p_i$ distinct pre-images each of multiplicity $n_i$; and hence so does $A_{\Gamma_i}$. Recall from Theorem~\ref{conf_mating_thm} that the map $S:\cT_i\cap\overline{\cD}\to\cT_i$  is conjugate to $A_{\Gamma_i}:\overline{\cU}_{\Gamma_i}\cap\D\to\D$, for all $i\in \{1, 2, \cdots, l\}$. The result now follows directly from Relation~\eqref{alg_char_eq}  (cf. \cite[Proposition~4.14]{mj2023matings}). 
\end{proof}

\begin{remark}
It is easy to see that $(\Sigma,\mathfrak{D},\eta,\mathcal{R})$ satisfying the conditions of Theorem~\ref{alg_weak_b_inv_thm} gives rise to a weak B-involution $S:\overline{\cD}\to\widehat{\C}$, where $\cD=\mathcal{R}(\mathfrak{D})$ and $S\big|_{\cD} \equiv \mathcal{R}\circ \eta\circ \big(\mathcal{R}\big|_{\mathfrak{D}}\big)^{-1}$. In fact, one can check that the quadruples $(\Sigma,\mathfrak{D},\eta,\mathcal{R})$ and the pairs $(S,\cD)$ are in bijective correspondence, up to appropriate equivalences.
\end{remark}

\begin{definition}
    For a weak B-involution $S:\overline{\cD}\to\widehat{\C}$ arising from the conformal mating construction of Theorem~\ref{conf_mating_thm}, the associated welded Riemann surface $\Sigma$ (defined in Theorem~\ref{alg_weak_b_inv_thm}) will be called the \emph{blender surface}. We call the map $\cR$, also defined in Theorem~\ref{alg_weak_b_inv_thm}, the \emph{uniformizing meromorphic map}.
\end{definition}

\begin{lem}\label{graph_eta_lem}
With notation as above, we have 
\begin{align*}
& \eta(\mathcal{C}_\Sigma)=\mathcal{C}_\Sigma\\
\iff & \widehat{\eta}(\mathcal{C}_\cG)=\mathcal{C}_\cG\\
\iff & \{i_1,\cdots,i_\alpha\}=\{j_1\cdots,j_\beta\}\\
\iff &\{i_1,\cdots,i_\alpha\}\cap\{j_1\cdots,j_\beta\}\neq\emptyset.
\end{align*}
\end{lem}
\begin{figure}[ht!]
\captionsetup{width=0.98\linewidth}
\includegraphics[width=0.96\linewidth]{welding_graph.png}
\caption{Left: Depicted are two disjoint, symmetric components $\mathcal{C}_\cG, \mathcal{C}_\cG'$ of a welding graph $\cG$. The vertices of $\mathcal{C}_\cG$ are mapped to those of $\mathcal{C}_\cG'$ under the involution $\widehat{\eta}$. Right: Depicted is a self-symmetric component $\mathcal{C}_\cG$ of a welding graph $\cG$. The induced map $\widehat{\eta}$ preserves the vertex set of $\mathcal{C}_\cG$.}
\label{weld_graph_fig}
\end{figure}
\begin{proof}
The equivalence of the first two statements is obvious from the definition of $\cG$ and the induced map $\widehat{\eta}$.

Suppose that $\widehat{\eta}(\mathcal{C}_\cG)=\mathcal{C}_\cG$. Since $\widehat{\eta}(v_i^\pm)=v_i^\mp$, it follows that $v_i^\pm\in V(\mathcal{C}_\cG)$ if and only if $v_i^\mp\in V(\mathcal{C}_\cG)$. Thus, $\{i_1,\cdots,i_\alpha\}=\{j_1\cdots,j_\beta\}$.

The third statement trivially implies the fourth.

Finally, let $i\in\{i_1,\cdots,i_\alpha\}\cap\{j_1\cdots,j_\beta\}$. Then $\Omega_i^-, \Omega_i^+\subset\mathcal{C}_\Sigma$. As $\eta$ carries $\Omega_i^-$ to $\Omega_i^+$, we have $\eta(\mathcal{C}_\Sigma)\cap\mathcal{C}_\Sigma\neq\emptyset$. But the homeomorphism $\eta$ must carry a component of $\Sigma$ to a component of $\Sigma$, and hence $\eta(\mathcal{C}_\Sigma)=\mathcal{C}_\Sigma$.
\end{proof}

\subsubsection{An auxiliary surface}
Consider a inversive multi-domain $\mathcal{D}$. The map $S$ is a conformal involution in a neighborhood of $\partial^0\cD$; this gives a pairing of the connected components of $\partial^0\mathcal{D}$. We construct a Riemann surface from $\cD\cup\partial^0\cD$ by welding the paired boundary components via $S$. The resulting surface would be a finite union of bordered Riemann surfaces of finite genus. Let us denote this surface by $\widecheck{\Sigma}^0$. 


\begin{theorem}\label{zipped_surface_thm}
    Let $(\Sigma, \widecheck{\Sigma}^0, \eta)$ be as above. Then the following hold.
    \begin{enumerate}\upshape
        \item $\widecheck{\Sigma}^0$ is a finite type surface.
        \item $\widecheck{\Sigma} \cong \Sigma/\langle\eta\rangle$, where $\widecheck{\Sigma}$ is the compactification of the surface $\widecheck{\Sigma}^0$ (obtained by filling in the punctures). In particular, the components of $\widecheck{\Sigma}$ correspond bijectively to the $\eta-$orbits of the components of $\Sigma$.
    \end{enumerate}
\end{theorem}
\begin{proof}
Recall that $\Sigma^0$ stands for the finite type surface obtained by gluing two copies of $\cD\cup\partial^0\cD$ via the boundary involution $S$, and $\Sigma$ is its compactification. Recall also the welding maps $\psi_1$ and $\psi_2$; the conformal embeddings of $\mathcal{D}\cup\partial^0\cD$ into $\Sigma$. Further, we have $\mathfrak{D}=\psi_1(\cD)$ and $\eta(\mathfrak{D})=\psi_2(\cD)$.
We will denote the boundary of $\mathfrak{D}$ in the punctured surface $\Sigma^0$ by $\partial^0\mathfrak{D}$, so that $\psi_1(\partial^0\cD)=\psi_2(\partial^0\cD)=\partial^0\mathfrak{D}$. The boundary of $\mathfrak{D}$ in the compact surface $\Sigma$ will be denoted by the usual notation $\partial\mathfrak{D}$. Then, we have $\Sigma = \mathfrak{D} \cup \eta(\mathfrak{D})\cup \partial\mathfrak{D}$, and $\Sigma^0 = \mathfrak{D} \cup \eta(\mathfrak{D})\cup \partial^0\mathfrak{D}$.

1) Let $\phi$ be the quotient map from $\mathcal{D}\cup \partial^0\mathcal{D}$ onto $\widecheck{\Sigma}^0$, coming from the welding construction of $\widecheck{\Sigma}^0$. It is evident that the map $\phi|_{\mathcal{D}}$ is a conformal embedding. 
Define the map $\mathcal{Q}: \Sigma^0 \rightarrow \widecheck{\Sigma}^0$ as
    \begin{equation*}
    \mathcal{Q}\equiv \begin{cases*}
      \phi\circ \psi_1^{-1} & on $\mathfrak{D}\cup \partial^0\mathfrak{D}$, \\
      \phi\circ \psi_2^{-1}        & on $\eta(\mathfrak{D})$.
    \end{cases*}
\end{equation*}
The map $\mathcal{Q}$ is clearly continuous on the (real-analytic) common boundary $\partial^0\mathfrak{D}$ because $\phi\equiv \phi\circ S$ on $\partial^0\cD$. This shows that $\mathcal{Q}$ is a degree $2$ holomorphic map from the finite type surface $\Sigma^0$ onto $\widecheck{\Sigma}^0$, and hence $\widecheck{\Sigma}^0$ is a finite type surface. 

2) By continuity of $\mathcal{Q}$, punctures in $\Sigma^0$ go to punctures in $\widecheck{\Sigma}^0$. This gives us an extended map $\mathcal{Q}:\Sigma \rightarrow \widecheck{\Sigma}$, where $\widecheck{\Sigma}$ is the compactification of $\widecheck{\Sigma}^0$ (by abuse of notation, we shall reuse the name $\mathcal{Q}$). Note that $\mathcal{Q}\circ\eta \equiv \mathcal{Q}$. In other words, the involution $\eta$ generates the group of deck transformations for $\mathcal{Q}$. Therefore, $\widecheck{\Sigma} \cong \Sigma/\langle\eta\rangle$.    
\end{proof}

\begin{remark}
If $\cD$ is an inversive domain (i.e., it is connected), then the associated welding graph $\cG$ and hence the welded surface $\Sigma$ as well as the auxiliary surface $\widecheck{\Sigma}$ are also connected. However, in general, the surfaces $\widecheck{\Sigma}$ and $\Sigma$ can be connected even if $\cD$ is disconnected (see Section~\ref{examples_sec}).
\end{remark}

\subsubsection{Components of blender surfaces are spheres or hyperelliptic}
We will now see that for a weak B-involution $S:\overline{\cD}\to\widehat{\C}$ constructed via the conformal mating procedure of Theorem~\ref{conf_mating_thm}, there are strong restrictions on the topology of the auxiliary surface $\widecheck{\Sigma}$. Indeed, regardless of the connectivities of the components of $\cD$, the components of $\widecheck{\Sigma}$ are necessarily simply connected. This, in turn, forces the blender surface $\Sigma$ to be made up of copies of Riemann spheres and hyperelliptic Riemann surfaces.

Recall from Theorem~\ref{zipped_surface_thm} that there exists a degree two meromorphic map $\mathcal{Q}:\Sigma\to\widecheck{\Sigma}\cong\Sigma/\langle\eta\rangle$ such that $\mathcal{Q}\circ\eta\equiv \mathcal{Q}$.


\begin{theorem}
\noindent\begin{enumerate}[leftmargin=8mm]\upshape
    \item For weak B-involutions arising from the conformal mating construction of Theorem~\ref{conf_mating_thm}, the surface $\widecheck{\Sigma}$ is a disjoint union of  Riemann spheres $\widehat{\C}$.
    \item Each component of the blender surface $\Sigma$ is either
    \begin{enumerate}
        \item a copy of the Riemann sphere that is mapped conformally to $\widehat{\C}$ by $\mathcal{Q}$, or
        \item a hyperelliptic Riemann surface (possibly the Riemann sphere) that is mapped as a degree $2$ branched covering to $\widehat{\C}$ by $\mathcal{Q}$.
    \end{enumerate} 
\end{enumerate}
\label{hyperelliptic_thm}
\end{theorem}

\begin{proof} 
1) Let $S:\overline{\cD}\to\widehat{\C}$ be a weak B-involution on an inversive multi-domain $\mathcal{D}$ realizing a conformal mating in the sense of Theorem~\ref{conf_mating_thm}. Let $V_1, V_2, \cdots, V_l$ be the components of $\widehat{\mathbb{C}}\setminus\overline{\cD}$. In other words, $\displaystyle T = \bigcup_{i = 1}^l\overline{V_i}$. 

We will now show that the process of passing from $\cD\cup\partial^0\cD$ to $\widecheck{\Sigma}^0$ amounts to zipping the holes $V_i$.
By the very nature of the (factor) Bowen-Series map construction, we see that $\partial V_i$ comes equipped with a line of symmetry, and $S\vert_{\partial V_i}$ is a topological reflection with respect to this line of symmetry. This line of symmetry connects (the projections of) two parabolic fixed points or order $2$ orbifold points of the corresponding Fuchsian group. Further, this line of symmetry divides $\partial V_i$ into $\partial V_i^+$ and $\partial V_i^-$. We define as follows an equivalence relation $\sim_{\text{zip}}$ on  $\widehat{\mathbb{C}}\setminus X$, where $X$ is the set of singular points on $\partial\Omega$. For $\displaystyle x, y \in \widehat{\mathbb{C}}\setminus X=\big(\mathcal{D}\cup\partial^0\mathcal{D}\big) \bigcup \big(\bigcup_{i = 1}^lV_i\big)$, we say that $x \sim_{\text{zip}} y$, if and only if for some $i\in \{1, 2, \cdots, l\}$, $x$ and $y$ belong to the closure of a hyperbolic geodesic of $V_i$ connecting some point $p \in \partial V_i^-\setminus X$ to $S(p)\in \partial V_i^+\setminus X$. Clearly, $\widecheck{\Sigma}^0 \cong \big(\widehat{\mathbb{C}}\backslash X\big)/\sim_{\text{zip}}$. It also follows from the above zipping constructing that for each $i\in\{1,\cdots,l\}$, the image of $\overline{V_i}\setminus X$ in $\big(\widehat{\mathbb{C}}\backslash X\big)/\sim_{\text{zip}}$ is the union of finitely many disjoint (possibly a single) simple arcs. This implies that $\big(\widehat{\mathbb{C}}\backslash X\big)/\sim_{\text{zip}}$ is a finite union of punctured spheres. Hence, its compactification $\widecheck{\Sigma}$ is a disjoint union of finitely many copies of Riemann spheres.

2) Recall from the discussion in Section~\ref{weld_graph_subsec} that there are two types of components of $\Sigma$: those that are preserved by the involution $\eta$, and those that lie in a $2-$cycle under $\eta$. If $\mathcal{C}_\Sigma$ is a component that lies in a $2-$cycle under $\eta$, then by definition, $\mathcal{Q}$ maps $\mathcal{C}_\Sigma \sqcup \eta(\mathcal{C}_\Sigma)$ to a component of $\widecheck{\Sigma}$, a Riemann sphere. Note that the degree of the map $\mathcal{Q}\big|_{\mathcal{C}_\Sigma}$ is $1$. This implies that both $\mathcal{C}_\Sigma$ and $\eta(\mathcal{C}_\Sigma)$ are Riemann spheres. Now let $\mathcal{C}_\Sigma$ be an $\eta$-invariant component of $\Sigma$. Then $\mathcal{Q}\big|_{\mathcal{C}_\Sigma}$ maps $\mathcal{C}_\Sigma$ to a component of $\widecheck{\Sigma}$, a Riemann sphere. This gives rise to a degree two meromorphic function on $\mathcal{C}_\Sigma$, forcing $\mathcal{C}_\Sigma$ to be hyperelliptic (possibly the Riemann sphere). 
\end{proof} 

\noindent The description of $\widecheck{\Sigma}$ given in Theorem~\ref{hyperelliptic_thm} motivates the following nomenclature.

\begin{definition}\label{zipped_def}
For a weak B-involution $S$ arising from the conformal mating construction of Theorem~\ref{conf_mating_thm}, the surface $\widecheck{\Sigma}$ will be called the \emph{zipped surface} associated with $S$.
\end{definition}


\begin{prop}\label{genus_prop}
Let $\displaystyle S:\overline{\cD} \to\widehat{\C}$, where $\cD:= \bigsqcup_{i=1}^k \Omega_i$, be a conformal mating produced in Theorem~\ref{conf_mating_thm} such that the associated welding graph $\cG$ is connected. Then $\Sigma$ is a compact Riemann surface of genus $g=\frac{\#\mathrm{Fix}(\eta)-2}{2}$, where $\mathrm{Fix}(\eta)$ denotes the set of fixed points of $\eta$. In particular, under the above assumptions, if $S$ has at least three fixed points on $\partial^0\cD$, then $g\geq 1$.
\end{prop}
\begin{proof}
By Theorems~\ref{zipped_surface_thm} and~\ref{hyperelliptic_thm}, the surface $\widecheck{\Sigma}$ is the Riemann sphere. Further, the critical points of the degree $2$ holomorphic map $\mathcal{Q}:\Sigma\to\Sigma/\langle\eta\rangle\cong\widecheck{\Sigma}\cong\widehat{\C}$ are precisely the fixed points of $\eta$. The result now follows from the Riemann-Hurwitz formula.

Recall that $\mathcal{R}:\partial^0\mathfrak{D}\to\partial^0\mathfrak{\cD}$ conjugates $\eta\vert_{\partial^0\mathfrak{D}}$ to $S\vert_{\partial^0\cD}$. Thus, if $S$ has at least three fixed points on $\partial^0\cD$, then $\eta$ has at least three fixed points on $\partial^0\mathfrak{D}$. The second statement now follows from this observation and the first part.
\end{proof}

\subsubsection{Constructing hyperelliptic blender surfaces}\label{construct_blender_subsec}
We now present an explicit construction of conformal matings $S:\overline{\cD}\to\widehat{\C}$ whose associated blender surfaces are connected, and hence hyperelliptic.



\begin{prop}\label{mating_surf_exists_prop}
    Let $\{\Gamma_i\}_{i=1}^l$ be Fuchsian groups (introduced in Section~\ref{mateable_maps_subsec}), with $A_{\Gamma_i}$ the associated (factor) Bowen-Series map for $\Gamma_i$, $i\in\{1,\cdots, l\}$. Let $\{B_j\}_{j=1}^r$ be hyperbolic Blaschke products. Then there exists a critically fixed polynomial $P$ with the following properties.
    {\upshape
    \begin{enumerate}[leftmargin=8mm]
        \item $P$, $\{A_{\Gamma_i}\}_{i=1}^l$, and $\{B_j\}_{j=1}^r$ can be conformally mated.
        \item Let $S$ be the conformal mating of $P$, $\{A_{\Gamma_i}\}_{i=1}^l$, and $\{B_j\}_{j=1}^r$.
        Then the corresponding blender surface $\Sigma$ is connected.
    \end{enumerate}
    }
\end{prop}

\begin{proof}
    1) Applying Lemma~\ref{combi_lem} to the set of positive integers 
    $$
   \displaystyle \{\text{deg}(A_{\Gamma_i})\vert_{\mathbb{S}^1}-1\}_{i=1}^l \bigcup \{\text{deg}(B_j)-1\}_{j=1}^r,
    $$ 
    we get a critically fixed polynomial $P$, whose $l+r$ finite critical points have the given multiplicities. By Theorem~\ref{conf_mating_thm}, $P$, $\{A_{\Gamma_i}\}_{i=1}^l$, and $\{B_j\}_{j=1}^r$ can be conformally mated. 

    2) Let $S: \overline{\mathcal{D}} \rightarrow \widehat{\mathbb{C}}$ be the associated weak $B$-involution, with $X$ the set of singular points on $\partial\cD$, and let $\widehat{\C}\setminus\overline{\mathcal{D}} = \bigcup_{i=1}^lV_i$.  We shall show that the corresponding blender surface $\Sigma$ is connected by showing that $\mathcal{D}$ is connected.
    Recall the David homeomorphism $H:\widehat{\C}\to\widehat{\C}$ from Theorem~\ref{conf_mating_thm}. By construction of $S$, each $V_i$ is contained in a Jordan domain $\mathfrak{U}_i:=H(U_i)$, where $U_i$ is a bounded Fatou component of $P$. Further, $\mathfrak{U}_i\cap\mathfrak{U}_j=\emptyset$ for $i\neq j$. It also follows from the construction of $S$ that each $V_i$ is a Jordan domain and $\partial V_i\cap\partial \mathfrak{U}_i$ is a subset of $X$. 
    By way of contradiction, suppose that $\mathcal{D}$ is disconnected. Then, there exist $k>1$ and a chain $V_{i_0}, V_{i_1}, \cdots, V_{i_{k-1}}$, such that $\partial V_{i_j}$ meets $\partial V_{i_{j+1}}$ at a point in $X$ for all $j\in\{0,\cdots,k-1\}$ (where $j+1$ is taken mod $k$). This implies that $\partial\mathfrak{U}_{i_j}$ touches $\partial\mathfrak{U}_{i_{j+1}}$ at a point in $X$ for all $j\in\{0,\cdots,k-1\}$ (where $j+1$ is taken mod $k$). But this contradicts the fact that the filled Julia set $K(P)$ of the polynomial $P$ is a full compact set and hence so is $H(K(P))$. Therefore, $\cD$ is connected.    
\end{proof}

\begin{cor}\label{orbifold_genus_cor}
   Given $\{\Gamma_i\}_{i = 1}^l$ and $\{B_j\}_{j=1}^r$, consider the weak B-involution $S: \overline{\mathcal{D}}\rightarrow \widehat{\mathbb{C}}$ and the blender surface $\Sigma$ constructed in Proposition~\ref{mating_surf_exists_prop}. Let $b$ be the number of orbifold points of order $2$ in $\displaystyle\bigsqcup_{i = 1}^l \mathbb{D}/\widehat{\Gamma}_i$, and $g$ the genus of the surface $\Sigma$. If $b\geq 3$, then $g\geq 1$.
\end{cor}

\begin{proof}
    By Proposition~\ref{genus_prop}, we see that if $S$ has at least three fixed points on $\partial^0\mathcal{D}$, then $g\geq 1$. Every orbifold point of order $2$ in $\mathbb{D}/\widehat{\Gamma}_i$, $i\in\{1,\cdots,l\}$, corresponds to a unique fixed point of $S$ on $\partial^0\mathcal{D}$. The corollary now follows from the assumption that~$b\geq 3$.  
\end{proof}

\section{A gallery of examples}\label{examples_sec}

In this section, we present a host of examples that guided our investigation leading to Theorem~\ref{mating_thm_intro}. We describe the conformal matings for several explicit examples of the rational map $R$, Fuchsian groups $\{\widehat{\Gamma}_i\}_{i=1}^l$, and hyperbolic Blaschke products $\{B_j\}_{j=1}^r$. More precisely, we invoke Theorem~\ref{conf_mating_thm} to get weak B-involutions $S:\overline{\cD}\rightarrow\widehat{\mathbb{C}}$, whose dynamics is equivalent to the dynamics of the constituents $R$, $\{A_{\Gamma_i}\}_{i=1}^l$, and $\{B_j\}_{j=1}^r$ on appropriate domains. We shall also describe the topology of the associated blender surface $\Sigma$ (arising from results in Section~\ref{b_involutions_sec}).  

Recall that in Section~\ref{mateable_maps_subsec}, for $p$ even, we used $\Gamma_{n, p}$ to denote two different groups corresponding to Cases~I and~II. Since the specific nature of the groups will play a role in this section, we reserve the notation $\Gamma_{n,p}$ for groups constructed as in Case~I, and the notation $\Gamma_{n,p}^2$ for groups constructed as in Case~II.

