    The domain $\cD$ is an annulus bound by the red and blue curves as shown in Figure~\ref{final_fig}. Let us denote the red curve by $\gamma_1$, and the blue curve by $\gamma_2$. Observe that welding two copies of $\cD$ along $\gamma_1$ via the map $S|_{\gamma_1}$ yields a genus $1$ surface with two boundary components; we call them $C_1$ and $C_2$ (cf. Figure~\ref{top_weld_surf_1_fig}). By construction, both $C_1$ and $C_2$ can be identified with $\gamma_2$, and the conformal involution $S|_{\gamma_2}$ induces an orientation-reversing analytic map $\widecheck{S}:C_1\rightarrow C_2$. Finally, gluing the two boundary components $C_1$ and $C_2$ via the map $\widecheck{S}$ would conclude the welding procedure by giving us a closed genus $2$ blender surface $\Sigma$. The uniformizing meromorphic map $\cR:\Sigma\rightarrow\widehat{\C}$ in this case has degree $8$ with a pole of order $7$ and a simple pole. Further, $\cR$ has a critical point of multiplicity $6$ (namely, the order $7$ pole),  a critical point of multiplicity $3$ (coming from $A_{\Gamma_{4,1}}^{\text{fBS}}$), three critical points of multiplicity $2$ each (coming from $A_{\Gamma_{3,1}}^{\text{fBS}}$), and three simple critical points (one from the Blaschke product $B$, and the other two from the singular points on $\partial\cD$). 
\end{example}

\begin{remark} Observe that if $\cD$ is connected, then both the surfaces $\Sigma$ and $\widecheck{\Sigma}$ are connected. On the other hand if $\cD$ is disconnected but $\Sigma$ is connected, then $\widecheck{\Sigma}\cong \Sigma/\langle\eta\rangle$ is also connected. Thus, with respect to connectedness of $\cD$, $\Sigma$, and $\widecheck{\Sigma}$, there are four distinct possibilities. We have demonstrated the occurrence of all four possibilities through Examples~\ref{000_ex} to \ref{111_ex}.
\end{remark}

\section{Correspondences on hyperelliptic surfaces}\label{correspondences_sec}

Let $S: \overline{\mathcal{D}} \rightarrow \widehat{\mathbb{C}}$ be the conformal mating of $R$, $\{A_{\Gamma_i}\}_{i = 1}^l$ and $\{B_j\}_{j = 1}^r$, as in Section~\ref{conf_mating_sec}.  The non-invertibility of the factor Bowen-Series maps $\{A_{\Gamma_i}\}_{i=1}^l$, that go into the construction of the conformal mating $S$, is an obstruction to the recovery of the full group structure of $\widehat{\Gamma}_i$ from the action of the map $S$ itself. To mitigate this problem, we will now use the the map $\cR$ to define an algebraic correspondence $\mathfrak{C}$ on the blender surface $\Sigma$ (where $\cR, \Sigma$ are associated with the weak B-involution $S$, see Theorem~\ref{alg_weak_b_inv_thm}). A careful analysis of the dynamics of $\mathfrak{C}$ facilitates the full reconstruction of the underlying Fuchsian groups $\{\widehat{\Gamma}_i\}_{i = 1}^l$, as well as the recovery of the maps $\{B_j\}_{j=1}^r$. This will demonstrate that the correspondence $\mathfrak{C}$ unites the actions of the groups $\widehat{\Gamma}_i$ and the Blaschke products $B_j$.


Let $\mathcal{R}$ and $\mathfrak{D}$ be as in Theorem~\ref{alg_weak_b_inv_thm}. Define a holomorphic correspondence $\mathfrak{C}\subset \Sigma \times \Sigma$ of bi-degree $d:d$ (cf. \cite{dinh2006distribution}) as
\begin{equation}
(z, w) \in \mathfrak{C} \iff \cR(w)=\cR(\eta(z)),\ w\neq \eta(z).
\label{corr_eq}
\end{equation}
Note that the equation $\cR(w)=\cR(\eta(z))$ defines a reducible holomorphic curve in $\Sigma\times\Sigma$, and $\{(z,w)\in\Sigma\times\Sigma: w=\eta(z)\}$ consists of a certain component thereof. The correspondence $\mathfrak{C}$ is defined by removing this component from the former curve.
We regard the correspondence $\mathfrak{C}$ as a multi-valued map: 
$$
z\mapsto w=\mathcal{R}^{-1}(\mathcal{R}(\eta(z))).
$$
Evidently, the local branches of the correspondences are defined by $\eta$ and the (local) deck transformations of $\cR$.

The explicit algebraic description of $S$ in Theorem~\ref{alg_weak_b_inv_thm} is captured in the following commutative diagram,

\begin{equation}
\begin{tikzcd}
	{\overline{\mathfrak{D}}} && {\overline{\mathcal{D}}} \\
	\\
	{\Sigma\backslash\mathfrak{D}} && {\widehat{\mathbb{C}}}
	\arrow["{\mathcal{R}}", from=1-1, to=1-3]
	\arrow["\eta",swap, from=1-1, to=3-1]
	\arrow["{\mathcal{R}}"', from=3-1, to=3-3]
	\arrow["S"',swap, from=1-3, to=3-3]
\end{tikzcd}
\label{alg_char_cd}
\end{equation}

\noindent As a consequence, we immediately get that for $z\in \overline{\mathfrak{D}}$,
\begin{equation}\label{forward_corr_eq}
 (z, w) \in \mathfrak{C} \iff \cR(w) = \cR(\eta(z)) = S(\cR(z)),\ \ w\neq \eta(z), 
\end{equation}
and for $z \in \Sigma\backslash\mathfrak{D}$,
\begin{equation}\label{backward_corr_eq}
    (z,w)\in \mathfrak{C} \iff \cR(w) = \cR(\eta(z)) = S^{-1}(\cR(z)),\ \ w\neq \eta(z),
\end{equation}
for a suitable inverse branch of $S^{-1}$.
\begin{remark}
    The brief discussion above shows that a forward branch of the correspondence $\mathfrak{C}$ sends $z$ to $w$ if and only if either the conformal mating $S$ or one of its inverse branches sends $R(z)$ to $R(w)$. In other words, the meromorphic map $\cR$ lifts the dynamics of $S$ to the correspondence $\mathfrak{C}$.
\end{remark}

Fix an index $i\in \{1, 2, \cdots, l\}$. Observe that points in every component of the escaping set $\cW_i$ of $S$ eventually map to $\cT_i$ before leaving the domain $\overline{\cD}$ of the conformal mating (see Remark~\ref{invariant_subset_rem} for the definition of $\cT_i$). 
For a component $C$ of $\cW_i$, let $C'$ be components of $\cW_i$ such that $S(C') = C$. If $C\neq \cT_i$, then by Relation~\ref{alg_char_cd},
\begin{equation}
\cR^{-1}(C) = \Bigg(\big(\cR\big|_{\mathfrak{D}}\big)^{-1}(C)\Bigg)\bigsqcup \Bigg(\bigsqcup_{C'}\eta\Big(\big(\cR\big|_{\mathfrak{D}}\big)^{-1}(C')\Big)\Bigg).
\label{preimage_formula_eq}
\end{equation}
\noindent On the other hand, if $C = \cT_i$, then for $\widecheck{C} = C\cap \overline{\cD}$, 
$$
\cR^{-1}(C) = \Bigg(\big(\cR\big|_{\overline{\mathfrak{D}}}\big)^{-1}(\widecheck{C})\Bigg)\bigcup\Bigg(\eta\Big(\big(\cR\big|_{\overline{\mathfrak{D}}}\big)^{-1}(\widecheck{C})\Big)\Bigg)\bigsqcup\Bigg(\bigsqcup_{C'\neq C} \eta\Big(\big(\cR\big|_{\mathfrak{D}}\big)^{-1}(C')\Big)\Bigg).
$$
In a nutshell, the involution $\eta$, restricted to $\mathfrak{D}$, mimics the action of $S$ on $\mathcal{D}$. Specifically, it maps components of $\cR^{-1}(C') \cap \mathfrak{D}$ to components of $\cR^{-1}(C) \cap \mathfrak{D}^c$, if $S$ maps $C'$ to $C$. Now define,
\begin{equation}
\widetilde{\cT_i}:= \big(\cR\big|_{\overline{\mathfrak{D}}}\big)^{-1}(\widecheck{\cT_i})\cup\eta\Big(\big(\cR\big|_{\overline{\mathfrak{D}}}\big)^{-1}(\widecheck{\cT_i})\Big)\subseteq \cR^{-1}(\cT_i),
\label{tiling_comp_eq}
\end{equation}
where $\widecheck{\cT_i} = \cT_i\cap\overline{\cD}$. By the construction of the blender surface $\Sigma$, the open set $\widetilde{\cT_i}$ is obtained by gluing two copies of $\widecheck{\cT}_i$ along $\partial\widecheck{\cT}_i\cap\partial^0\cD$ via the weak B-involution $S$. Consequently, $\widetilde{\cT}_i$ is a disjoint union of $p_i$ topological disks (cf. \cite[Lemma~5.3, Figure~10]{mj2023matings}). By Corollary~\ref{crit_points_cor} and Relation~\ref{alg_char_eq}, the map $\cR$ carries each component of $\widetilde{\cT_i}$ as an $n_i:1$ branched cover onto $\cT_i$, and when $n_i\geq 3$, each component of $\widetilde{\cT_i}$ contains a unique critical point of $\cR$ of multiplicity $n_i-1$.

\begin{remark}\label{tesselation_rem}
    The tessellation of the unit disk $\mathbb{D}$ by the group $\Gamma_i$ can be transferred to the domain $\cT_i$. Define the rank zero tile as $\cT^0_i = \cT_i \setminus \cD$. The rank $m$ tiles are the connected components of the pre-image $S^{-m}(\cT^0_i)$. Every point in $\cT_i$ lies in a rank $m$ tile for some $m \geq 0$, and the action of $S$ maps each rank $m\geq 1$ tile to a rank $m-1$ tile. Therefore, all points in $\cT_i \cap \overline{\cD}$ eventually escape to the “hole” (i.e., the rank zero tile).

This dynamical tessellation can be lifted via the map $\cR|_{\widetilde{\cT}_i}$ to obtain a similar tiling structure in $\widetilde{\cT}_i$. A rank $m$ tile in $\widetilde{\cT}_i$ is defined as a connected component of the pre-image under $\cR|_{\widetilde{\cT}_i}$ of a rank $m$ tile in $\cT_i$. We denote the rank zero tile(s) in $\widetilde{\cT}_i$ by $\widetilde{\cT}_i^0$; these are the $p_i$ disjoint pre-images of $\cT^0_i$, one in each component of $\widetilde{\cT}_i$.
\end{remark}


\begin{remark}\label{esc_inv_rem}
The set $\widetilde{\cT_i}$ is invariant under $\eta$, which brings to attention a stark difference between the dynamics of the correspondence $\mathfrak{C}$ and the conformal mating $S$. While the points of $\cW_i$ eventually escape $\cD$ under the iterates of $S$; points in $\widetilde{\cW}_i$ ``eventually" map to $\widetilde{\cT_i}$, after which they remain  in $\widetilde{\cT_i}$ under $\eta$ as well as under suitable local deck transformations of $\cR$. In other words, by lifting the dynamics of the conformal mating $S$ to that of the correspondence $\mathfrak{C}$, we managed to suppress the escaping behavior exhibited by the former. Broadly speaking, we shall employ this philosophy to recover from $\mathfrak{C}$ the groups $\{\widehat{\Gamma}_i\}_{i=1}^l$. 
\end{remark}


Now fix an index $j\in \{1, 2, \cdots, r\}$ and define, 
\begin{equation}
\widetilde{\cV}_j:= \big(\cR\big|_{\mathfrak{D}}\big)^{-1}(\cV_j)\sqcup\eta\Big(\big(\cR\big|_{\mathfrak{D}}\big)^{-1}(\cV_j)\Big)\subseteq \cR^{-1}(\cV_j),
\label{blaschke_comp_eq}
\end{equation}
(see Remark~\ref{invariant_subset_rem} for the definition of $\cV_j$). By definition, $\widetilde{\cV}_j$ is a disjoint union of a pair of topological disks. By Theorem~\ref{conf_mating_thm} and Relation~\ref{alg_char_eq}, the map $\cR$ carries the component of $\widetilde{\cV}_j$ lying in $\mathfrak{D}$ univalently onto $\cV_j$; while the other component maps onto $\cV_j$ as a $(\deg(B_j)-1):1$ branched cover. 

As in Relation~\ref{preimage_formula_eq}, given a component $C$ of $\cW_{l+j}$, the pre-image $\cR^{-1}(C)$ can be written down explicitly in terms of components $C'$ of $\cW_{l+j}$ such that $S(C') = C$. 

Define $\mathfrak{C}_i:= \mathfrak{C}\cap\big(\widetilde{\cT}_i \times \widetilde{\cT}_i\big)$. One can think of $\mathfrak{C}_i$ as a multi-valued map:
\begin{equation}\label{restricted_corr_eq}
   z\mapsto w = \Big(\cR\big|_{\widetilde{\cT}_i}\Big)^{-1}\bigg(\Big(\cR\big|_{\widetilde{\cT}_i}\Big)(\eta(z))\bigg), 
\end{equation}
where the local branches are generated by $\eta$ and the local deck transformations of the branched covering map $\cR\big|_{\widetilde{\cT_i}}: \widetilde{\cT_i} \rightarrow\cT_i$. In the coming two subsections we shall prove the following theorem (cf. \cite[Theorem~5.2]{mj2023matings}). We recall the notation $\widehat{\Gamma}_i = \langle\Gamma_i, M_{\omega_i}\rangle$ from Section~\ref{fBS_subsec}.

\begin{theorem}\label{corr_recover_thm}
    The correspondence $\mathfrak{C}$ is a mating of the groups $\{\widehat{\Gamma}_i\}_{i=1}^l$, and the Blaschke products $\{B_j\}_{j=1}^r$, in the following sense.
    \begin{enumerate}[leftmargin=8mm]
        \item The action of $\mathfrak{C}_i$ on $\widetilde{\cT_i}$ is equivalent to the action of a group $\langle\eta, \tau_i\rangle$ of conformal automorphisms of $\widetilde{\cT_i}$, $i\in\{1,\cdots, l\}$. Moreover, the above group acts properly discontinuously, and the quotient orbifold $\widetilde{\cT_i}/\mathfrak{C}_i$ is biholomorphic to~$\mathbb{D}/\widehat{\Gamma}_i$.

        \item The correspondence $\mathfrak{C}$ has a forward branch (respectively, a backward branch) carrying $\widetilde{\cV}_j\cap \mathfrak{D}$ (respectively, $\widetilde{\cV}_j\setminus \overline{\mathfrak{D}}$) onto itself, and this branch is conformally conjugate to the Blaschke product $B_j$, $j\in\{1,\cdots,r\}$.
    \end{enumerate}
\end{theorem}

The proof would be split as follows. In Section~\ref{group-like_subsubsec} we shall study the action of $\mathfrak{C}$ on $\widetilde{\cT_i}$, $i\in\{1,\cdots, l\}$, to recover the groups $\{\widehat{\Gamma}_i\}_{i=1}^l$, and establish the quotient orbifold equivalence $\widetilde{\cT_i}/\mathfrak{C}_i\cong \mathbb{D}/\widehat{\Gamma}_i$. In Section~\ref{map-like_subsubsec}, we will study the action of $\mathfrak{C}$ on $\widetilde{\cV}_j$, to recover the Blaschke products $\{B_j\}_{j=1}^r$.

\subsection{Group-like dynamics in $\mathfrak{C}$}\label{group-like_subsubsec}Fix an index $i\in \{1, 2, \cdots, l\}$. Recall (from the proof of Theorem~\ref{conf_mating_thm}) the conformal map $\mathfrak{X}_i:\mathbb{D}\rightarrow\cT_i$ that satisfies
\begin{equation}\label{fBS_conj_eq}
     \mathfrak{X}_i \circ A^{\text{fBS}}_{\Gamma_i} =  S \circ \mathfrak{X}_i
\end{equation}
on appropriate regions. This map sends the origin in the dynamical plane of $A_{\Gamma_i}$ to a point in $\cT_i$; we will refer to this image point as a \emph{distinguished point}. 

Note that each component of $\widetilde{\cT}_i$ contains a unique pre-image of the distinguished point under $\cR$. If $n_i\geq 3$, the point $0$ is the unique critical value of $A_{\Gamma_i}$, and hence the distinguished point would be the unique critical value of $\cR\vert_{\widetilde{\cT}_i}$ in $\cT_i$. Further, each component of $\widetilde{\cT}_i$ contains a pre-image of the distinguished point (under the map $\cR$) that maps to it with local degree $n_i$.   

\begin{lem}\label{aut_corr_lem}
    The open set $\widetilde{\cT_i}$ admits a biholomorphism $\tau_i$ such that
    $$\tau^{n_ip_i}_i\equiv \text{id}, \hspace{2mm} and \hspace{2mm}\Big(\cR\big|_{\widetilde{\cT}_i}\Big)^{-1}\bigg(\Big(\cR\big|_{\widetilde{\cT}_i}\Big)(z)\bigg) = \{z, \tau_i(z), \cdots, \tau_i^{n_ip_i-1}(z)\} \hspace{2mm}\forall z\in \widetilde{\cT_i}.$$
\end{lem}

\begin{proof}
    Enumerate the $p_i$ components of $\widetilde{\cT_i}$ by the index set $\cI:=\{1,\cdots,p_i\}$. Let $\Phi: \mathbb{D}\times\cI\rightarrow \widetilde{\cT_i}$ be a biholomorphism such that for each $j\in \cI$, the map $\Phi$ sends $(0, j)$ to the unique pre-image of the distinguished point (of $\cT_i$) in the $j$-th component of $\widetilde{\cT_i}$. Therefore, after possibly pre-composing $\Phi$ with a rotation on each $\mathbb{D}\times\{j\}$, we can write $\widetilde{\cR}:= \mathfrak{X}_i^{-1}\circ \cR\circ \Phi:\mathbb{D}\times\cI\rightarrow \D$ as
\begin{equation}\label{auxillary_cover_eq}
    (w, j) \mapsto w^{n_i}, \hspace{2mm}w\in \mathbb{D}, \hspace{1mm}j\in \cI.
    \end{equation}
    Now define the map $\widetilde{\tau}_i:\mathbb{D}\times\cI\rightarrow\mathbb{D}\times\cI$ as follows,
\begin{equation}\label{auxillary_aut_eq}
    \widetilde{\tau}_i(w, j):= \begin{cases*}
        (w, j+1), & $\text{for } j \in \{1, \cdots, p_i-1\}$\\
        (e^{\frac{2i\pi}{n_i}}w, 1), & $\text{for } j = p_i$.
    \end{cases*}
    \end{equation}
    One can check using Formulas~\eqref{auxillary_cover_eq} and~\eqref{auxillary_aut_eq} that, 
    $$
    \widetilde{\tau}_i^{n_ip_i} = \text{id}, \hspace{2mm} \text{and  }\widetilde{\cR}^{-1}(\widetilde{\cR}(w, j)) = \{(w, j), \widetilde{\tau}(w, j), \cdots, \widetilde{\tau}^{n_ip_i-1}(w, j)\},
    $$
    for $(w, j) \in \mathbb{D}\times\cI$. The required automorphism $\tau_i$ is given by $\Phi\circ\widetilde{\tau}_i\circ\Phi^{-1}$.
\end{proof}

\begin{cor}\label{group_action_corr}
    The dynamics of $\mathfrak{C}_i$ on $\widetilde{\cT}_i$ is equivalent to the action of the group $\langle\eta, \tau_i\rangle$ of conformal automorphisms of $\widetilde{\cT}_i$.
\end{cor}

\begin{proof}
    By Lemma~\ref{aut_corr_lem} it is clear that the forward branches of $\mathfrak{C}_i$ on $\widetilde{\cT}_i$ are given by $\tau_i\circ\eta, \cdots, \tau^{n_ip_i-1}_i\circ\eta$. Thanks to the relation $\tau_i = (\tau_i^2\circ\eta)\circ(\tau_i\circ\eta)^{-1}$, we conclude that
    $$
    \langle\tau_i\circ\eta, \cdots, \tau^{n_ip_i-1}_i\circ\eta\rangle = \langle\eta, \tau_i\rangle.
    $$
    Hence, the corollary follows.
\end{proof}

\begin{prop}\label{orbifold_isom_prop}
    The group $\langle\eta, \tau_i\rangle$ acts properly discontinuously on $\widetilde{\cT_i}$, and the quotient orbifold $\widetilde{\cT_i}/\langle\eta, \tau_i\rangle$ is biholomorphic to $\mathbb{D}/\widehat{\Gamma}_i$. 
\end{prop}

\begin{proof}
Let $\Phi$ be as in the proof of Lemma~\ref{aut_corr_lem}. Recall that $\widetilde{\cT}_i$ has $p_i$ components $\dT_{i,1}, \dT_{i,2}, \cdots, \dT_{i, p_i}$, where $\dT_{i,j} := \Phi(\mathbb{D}\times\{j\})$, for $1\leq j\leq p_i$. The interiors of these $p_i$ components divide $\partial\mathfrak{D}\cap\widetilde{\cT}_i$ into $p_i$ open arcs. We shall refer to the collection of these $p_i$ open arcs as the collection of \emph{welding lines}. 

Note that $\Phi\vert_{\D\times\{j\}}$ maps $\text{int}(\psi_{\rho_i}(\Pi))\times\{j\})$ conformally onto $\dT_{i,j}\cap\text{int}\widetilde{\cT}^0_i$, and extends homeomorphically to the boundary (in $\mathbb{D}\times\{j\}$).  After possibly pre-composing the maps $\Phi|_{\D\times\{j\}}$ with suitable powers of $M_{\omega_i}$, we can assume that $\Phi\vert_{\D\times\{j\}}$ takes the bi-infinite geodesic $\psi_{\rho_i}(C_{1,j})\times\{j\}\subset \partial\psi_{\rho_i}(\Pi)\times\{j\}$ to the welding line in $\dT_{i,j}$, for $1\leq j\leq p_i$. Let 
    $$
    G_j:= \{f\in \langle\eta, \tau_i\rangle: f(\dT_{i,j}) = \dT_{i,j}\}
    $$
    be the stabilizer of $\dT_{i,j}$ under the action of $\langle\eta, \tau_i\rangle$. 
Note that by definition, the cyclic group $\langle\tau_i\rangle$ generated by the conformal automorphism $\tau_i$ acts transitively on the components of $\widetilde{\cT}_i$. Therefore, it is enough to show that $G_1$ acts properly discontinuously on $\dT_{i,1}$, and that the quotient orbifold $\dT_{i,1}/G_1$ is biholomorphic to $\mathbb{D}/\widehat{\Gamma}_i$. Observe that from the proof of Lemma~\ref{aut_corr_lem}, we have the following commutative diagram.
    \begin{equation}\label{prop6.8_comm_eq}
        \begin{tikzcd}
	   {\mathbb{D}\times\{j\}} && \dT_{i,j} \\
	\\
	{\mathbb{D}} && {\mathcal{T}_i}
	\arrow["{\Phi|_{\mathbb{D}\times\{j\}}}", from=1-1, to=1-3]
	\arrow["{\widetilde{\mathcal{R}}|_{\mathbb{D}\times\{j\}}}"', from=1-1, to=3-1]
	\arrow["{\mathcal{R}}", from=1-3, to=3-3]
	\arrow["{\mathfrak{X}_i}"', from=3-1, to=3-3]
\end{tikzcd}
    \end{equation}

\noindent For the sake of brevity, for $1\leq j\leq p_i$, we denote $\widetilde{\cR}|_{\mathbb{D} \times \{j\}}$ simply by $\widetilde{\cR}_j$, the restriction $\cR|_{\dT_{i,j}}$ by $\cR_j$, and $\Phi|_{\mathbb{D} \times \{j\}}$ by $\Phi_j$.  By definition of (factor) Bowen-Series maps (see Section~\ref{fBS_subsec}), we have, 
\begin{equation}\label{fbS_def_eq}
    \widetilde{\cR}_j\circ A^{\text{BS}}_{\Gamma_i} = A^{\text{fBS}}_{\Gamma_i}\circ \widetilde{\cR}_j,\ \mathrm{on}\ \left( \D\setminus\Int{\psi_{\rho_i}(\Pi)} \right)\times\{j\},
\end{equation}
where by $A^{\text{BS}}_{\Gamma_i}$ we mean the possibly discontinuous Bowen-Series map that descends down to $A^{\text{fBS}}_{\Gamma_i}$ under the $n_i$-fold branched cover $w\mapsto w^{n_i}$. In addition, by the definition of $\widetilde{\tau}_i$ and $\tau_i$, we see that the following holds,
\begin{equation}\label{uniformising_maps_eq}
    \tau_i^{j-1}\circ\Phi_1\circ\widetilde{\tau}_i^{-(j-1)} = \Phi_j,\ \mathrm{on}\ \D\times\{j\}.
\end{equation}
Now by Relation~\ref{prop6.8_comm_eq}, there exists a local inverse branch of $\cR_j$ for which the following identity holds between the germs of functions near $\partial \psi_{\rho_i}(C_{1,j})\times\{j\}$, for $1\leq j\leq p_i$.

\begin{equation}\label{long_derivation_eq}
    \begin{split}
        \Phi_j\circ A_{\Gamma_i}^{\text{BS}} &= (\cR^{-1}_j\circ\mathfrak{X}_i\circ\widetilde{\cR}_j)\circ A_{\Gamma_i}^{\text{BS}}\\
        &= \cR^{-1}_j\circ\mathfrak{X}_i\circ A_{\Gamma_i}^{\text{fBS}}\circ \widetilde{\cR}_j \hspace{2mm}\text{        (by \ref{fbS_def_eq})}\\
        &= \cR^{-1}_j\circ S\circ\mathfrak{X}_i\circ\widetilde{\cR}_j\hspace{2mm}\text{        (by \ref{fBS_conj_eq})}\\
        &= \cR^{-1}_j\circ S\circ\mathfrak{X}_i\circ(\mathfrak{X}_i^{-1}\circ \cR_j\circ \Phi_j)\hspace{2mm}\text{        (by definition of }\widetilde{\cR})\\
        &= \cR^{-1}_j\circ S\circ\cR_j\circ \Phi_j\\
        &= \cR^{-1}_j\circ\cR_j\circ\eta\circ \Phi_j\hspace{2mm}\text{        (by \ref{alg_char_cd})}\\ 
        &= f_j\circ\Phi_j,\hspace{2mm}\text{  
        (for some }f_j\in G_j).
    \end{split}
\end{equation}
Note that the local germ of $\Phi_j\circ A_{\Gamma_i}^{\text{BS}}\circ \Phi^{-1}_j$, near $\Phi_j\left(\partial \psi_{\rho_i}(C_{1,j})\times\{j\}\right)$, is precisely the local germ of the generator $\rho_i(g_{1,j})$ of $\Gamma_i$, conjugated by $\Phi_j$. 
We denote by $\gamma_j\in G_1$ the element $\tau_i^{-(j-1)}\circ f_j\circ \tau_i^{j-1}$, and note that
by Equations~\eqref{uniformising_maps_eq} and~\eqref{long_derivation_eq}, we have the relation
\begin{equation}\label{generators_eq}
    \widetilde{\tau}_i^{-(j-1)}\circ A_{\Gamma_i}^{\text{BS}}\circ\widetilde{\tau}_i^{j-1} = \Phi_1^{-1}\circ\tau_i^{-(j-1)}\circ f_j\circ \tau_i^{j-1}\circ \Phi_1=\Phi_1^{-1}\circ\gamma_j\circ \Phi_1,  
\end{equation}
near $\partial \psi_{\rho_i}(C_{1,j})\times\{1\}$.

Further, by construction, $\tau_i^{p_i}$ restricts to an order $n_i$ automorphism of $\dT_{i,1}$, and $\Phi_1$ conjugates $M_{\omega_i}$ to $\tau_i^{p_i}$. Therefore, it follows by the Identity Theorem and Equations~\eqref{long_derivation_eq} and~\eqref{generators_eq} that the generators of $\widehat{\Gamma}_i$, under conjugation by $\Phi_1$, generate $G_1$. Set 
$$
\mathfrak{S}:= \Phi_1(\psi_{\rho_i}(\widehat{\Pi})),
$$
\noindent where $\widehat{\Pi}$ is the fundamental domain of $\widehat{\Gamma}_{n_i, p_i}$ (see Section~\ref{fBS_subsec}). The maps $\{\gamma_j\}_{j\in \cI}$ and $\tau_i^{p_i}$ furnish the closed fundamental domain $\mathfrak{S}$ with side-pairings that are conjugate to the preferred side-pairing transformations of $\widehat{\Gamma}_i$.


 It now follows that the group $\langle\eta, \tau_i\rangle$ acts properly discontinuously on $\widetilde{\cT}_i$, admitting $\mathfrak{S}$ as its closed fundamental domain. And finally, the map $\Phi$ would descend down the quotient to give an explicit biholomorphism between the orbifolds $\widetilde{\cT_i}/\langle\eta, \tau_i\rangle$ and $\mathbb{D}/\widehat{\Gamma}_i$.  
\end{proof}


\begin{remark}\label{recover_rep_rem}
       The involution $\eta$ permutes the $p_i$ components of $\widetilde{\cT}_i$, as the set $\widetilde{\cT}_i$ is $\eta$-invariant. Let us denote this permutation by $\sigma_i$. Notably, $\sigma_i$ coincides with the permutation of the bi-infinite geodesics $\{\psi_{\rho_i}(C_{1,j})\}_{j=1}^{p_i}$, induced by the side-pairing transformations of $\Gamma_i$ on $\partial\psi_{\rho_i}(\Pi)$. By Lemma~\ref{aut_corr_lem}, the map $f_j$ in the proof of Proposition~\ref{orbifold_isom_prop} is of the form $\tau_i^{k_j}\circ\eta$, for some $1\leq k_j\leq p_i$, where $k_j$ is dictated by the permutation $\sigma_i$. Now note that by Equation~\ref{generators_eq}, the representation $(\widehat{\rho}_i:\widehat{\Gamma}_{n_i,p_i}\rightarrow\widehat{\Gamma}_i)\in \text{Teich}(\widehat{\Gamma}_{n_i,p_i})$ can be equivalently defined as follows:
       \begin{equation*}
           \widehat{\rho}_i(g_{1,j}):= \Phi_1^{-1}\circ\tau_i^{-(j-1)}\circ (\tau_i^{k_j}\circ\eta)\circ \tau_i^{j-1}\circ\Phi_1,\hspace{2mm}\text{and}\hspace{2mm}\widehat{\rho}_i(M_{\omega_i}):= \Phi_1^{-1}\circ\tau_i^{p_i}\circ\Phi_1 = M_{\omega_i}.
       \end{equation*}
       Therefore, the action of the multi-valued map $\mathfrak{C}_i$ on $\widetilde{\cT}_i$, helps us recover not only the group $\widehat{\Gamma}_i$, but also the representation $\widehat{\rho}_i$ in $\text{Teich}^{\omega_i}(\Gamma_{n_i,p_i})$.   
\end{remark}

\subsection{Map-like dynamics in $\mathfrak{C}$}\label{map-like_subsubsec} Fix an index $j\in \{1, 2, \cdots, r\}$. In the following proposition, we shall prove the second part of Theorem~\ref{corr_recover_thm}.

\begin{prop}\label{recover_Blaschke_prop}
    There exists a forward branch (respectively, a backward branch) of $\mathfrak{C}$ carrying $\widetilde{\cV}_j\cap \mathfrak{D}$ (respectively, $\widetilde{\cV}_j\setminus \overline{\mathfrak{D}}$) onto itself, and this branch is conformally conjugate to the Blaschke product $B_j$.
\end{prop}
\begin{proof}
    The map
    $$
    \Big(\cR\big|_{\mathfrak{D}}\Big)^{-1}\circ R\circ \eta: \widetilde{\cV}_j\cap \mathfrak{D}\rightarrow\widetilde{\cV}_j\cap \mathfrak{D}
    $$
    is a forward branch of the correspondence $\mathfrak{C}$, and clearly it is conformally conjugate to $S\big|_{\cV_j}$ via the univalent map $\cR: \widetilde{\cV}_j\cap \mathfrak{D}\rightarrow \cV_j$. Further, it is easy to see that the map 
    $$
    \eta\circ \Big(\cR\big|_{\mathfrak{D}}\Big)^{-1}\circ R: \widetilde{\cV}_j\setminus \overline{\mathfrak{D}} \rightarrow \widetilde{\cV}_j\setminus \overline{\mathfrak{D}}
    $$
    is a backward branch of $\mathfrak{C}$. The involution $\eta$ restricts to a conformal conjugacy between the backward and forward branches of the correspondence $\mathfrak{C}$. Now, since $S\big|_{\cV_j}$ is conformally conjugate to $B_j$, the result follows.
\end{proof}


\begin{remark}
    Let $\mathcal{Z}:=\Sigma\setminus\bigcup_{i=1}^{l+r} \widetilde{\cW}_i$. Suppose that $\cR$ is injective on $\overline{\mathfrak{D}}$. Then, by replacing $\widetilde{\cV}_j\cap \mathfrak{D}$ (respectively, $\widetilde{\cV}_j\setminus \overline{\mathfrak{D}}$) with $\mathcal{Z}\cap \overline{\mathfrak{D}}$ (respectively, $\mathcal{Z}\setminus \mathfrak{D}$) in Proposition~\ref{recover_Blaschke_prop}, we obtain a topological conjugacy between $R$ and a forward branch (respectively, a backward branch) of the correspondence $\mathfrak{C}$, carrying $\mathcal{Z}\cap \overline{\mathfrak{D}}$ (respectively, $\mathcal{Z}\setminus \mathfrak{D}$) onto itself. Otherwise, one needs to pass to a nodal surface where the map $\cR$ descends to an injective map. This is precisely why a nodal surface was constructed in \cite[\S 5.2]{mj2023matings} to describe matings of Fuchsian groups with polynomials whose Julia sets are not Jordan curves.
\end{remark}

\subsection{Unification of Fuchsian groups and Blaschke products in correspondences}\label{unify_subsec}

We now combine the results proved so far to establish the main theorem of this section, i.e., Theorem~\ref{corr_recover_thm}. This is followed by two concrete instantiations, illustrating examples from Section~\ref{examples_sec}. Finally, we complete the proof of Theorem~\ref{mating_thm_intro}, thereby concluding a key component of the narrative introduced in Section~\ref{intro_sec}.

\begin{proof}[Proof of Theorem~\ref{corr_recover_thm}]
The first item is the content of Corollary~\ref{group_action_corr} and Proposition~\ref{orbifold_isom_prop}, while the second item follows from Proposition~\ref{recover_Blaschke_prop}.  
\end{proof}

\subsubsection{Illustrations}
1) Let $S:\overline{\cD}\rightarrow\widehat{\mathbb{C}}$ be a conformal mating as in Example~\ref{111_ex}. The domain $\cD$ is an annulus bound by a blue teardrop-shaped Jordan curve and a red topological quadrilateral (see Figure~\ref{111_fig}). The groups $\Gamma_1$ and $\Gamma_2$ that go into the construction of $S$ are $\Gamma_1:=\Gamma_{3,1}$ and $\Gamma_2:=\rho(\Gamma_{1, 4}^2)$, for some $(\rho:\Gamma_{1, 4}^2\rightarrow\Gamma_2)\in\text{Teich}(\Gamma_{1,4}^2)$. Here, the set $\widetilde{\cT_1}$ is an $\eta$-invariant topological disk, and the set $\widetilde{\cT}_2$ is a union of four topological disks; two of which are $\eta$-invariant, while the other two form a $2$-cycle under $\eta$. The associated correspondence $\mathfrak{C}$, which is defined on a torus, combines the actions of a quadratic Blaschke product $B$, and the groups $\Gamma_1, \Gamma_2$.

2) Let $S:\overline{\cD}\rightarrow\widehat{\mathbb{C}}$ be a conformal mating as in Example~\ref{111''_ex}. The triply connected domain $\cD$ is bound by a red cardioid-shaped Jordan curve, a blue triangle, and a blue quadrilateral (see Figure~\ref{111''_fig}). The groups $\Gamma_1, \Gamma_2$, and $\Gamma_3$ used to manufacture $S$ are $\Gamma_1:=\Gamma_{5,1}$, $\Gamma_2:=\Gamma_{1,3}$, and $\Gamma_3:=\rho(\Gamma_{1, 4}^2)$, for some $(\rho:\Gamma_{1, 4}^2\rightarrow\Gamma_3)\in\text{Teich}(\Gamma_{1,4}^2)$. In this case, the set $\widetilde{\cT_1}$ is an $\eta$-invariant topological disk, $\widetilde{\cT}_2$ is a union of three topological disks (one of which is $\eta$-invariant, while the other two form a $2$-cycle under $\eta$), and $\widetilde{\cT}_3$ is a union of four topological disks (two of which are $\eta$-invariant, while the other two form a $2$-cycle under $\eta$). The associated correspondence $\mathfrak{C}$, which is defined on a hyperelliptic Riemann surface of genus $2$, combines the actions of the groups $\Gamma_1, \Gamma_2$, and $\Gamma_3$.

\begin{prop}\label{uniqueness_standard_mating_prop}
    Let $S:\overline{\cD}\rightarrow\widehat{\C}$ and $S':\overline{\cD'}\rightarrow\widehat{\C}$ be two standard conformal matings associated with the collections $\{\Gamma_i\}_{i=1}^l$ and $\{B_j\}_{j=1}^r$. Then there exists a M{\"o}bius map $M$ such that $S_1 = M\circ S_2\circ M^{-1}$.
\end{prop}
\begin{proof}
    Let us denote by $\{\mathfrak{X}_i\}_{i=1}^{l+r},\ \mathfrak{X}_P$, and by $\{\mathfrak{X}'_i\}_{i=1}^{l+r},\ \mathfrak{X}'_P$, the conformal conjugacies associated with the maps $S$ and $S'$, respectively (see the proof of Theorem~\ref{conf_mating_thm}). For $1 \leq i \leq l$, the map $S$ is univalent on every component of $\mathcal{W}_i$ except $\mathcal{T}_i$. Similarly, for $1 \leq j \leq r$, $S$ is univalent on every component of $\mathcal{W}_{l+j}$ except $\mathcal{V}_j$. An analogous statement holds for $S'$ in its domain of definition $\overline{\mathcal{D}'}$. Therefore, for each $1\leq i\leq l+r$, the maps, $\mathfrak{X}_P'\circ\mathfrak{X}_P^{-1}$, $\mathfrak{X}_i'\circ\mathfrak{X}_i^{-1}$, and,
    $$
    (S')^{-n}\circ\mathfrak{X}_i'\circ\mathfrak{X}_i^{-1}\circ S^{\circ n},
    $$ 
    defined on the pre-images $\left\{S^{-n}\left(\overline{\cT}_i\right)\right\}_{i=1}^l$ and $\left\{S^{-n}\left(\overline{\cV_j}\right)\right\}_{j=1}^r$, for $n\geq 1$, patch together to give a homeomorphism $M:\widehat{\C}\rightarrow\widehat{\C}$, that is conformal away from $\mathfrak{X}_P(\mathcal{J}(P))$. The basin of infinity of $P$ is a John domain \cite[Chapter~7, Theorem~3.1]{carleson1996complex}; hence $\mathcal{J}(P)$ is $W^{1,1}-$removable \cite{jones2000removability}. By \cite[Theorem~2.7]{lyubich2020david}, the set $\mathfrak{X}_P(\mathcal{J}(P))$ is conformally removable. Thus, the map $M$ extends conformally to all of $\widehat{\C}$ giving the desired M\"obius map. 
\end{proof}

For a standard conformal mating $S:\overline{\cD}\rightarrow\widehat{\C}$ (as above), let $\Sigma$ and $\cR$ be the associated blender surface and the uniformizing meromorphic map, respectively. The following proposition records the extent of uniqueness of such an association.

\begin{prop}\label{uniqeness_of_mero_prop}
    Suppose there exist $4$-tuples $(\Sigma_1, \cR_1, \mathfrak{D}_1, \eta_1)$, $(\Sigma_2, \cR_2, \mathfrak{D}_2, \eta_2)$ satisfying:
    \begin{enumerate}
        \item $\eta_i$ is an involution of $\Sigma_i$, with $\eta_i(\partial\mathfrak{D}_i) = \partial\mathfrak{D}_i$,
        \item $\cR_i|_{\mathfrak{D}_i}$ is injective,
        \item $\cR_i(\overline{\mathfrak{D}_i}) = \overline{\cD}$, and,
        \item $S|_{\overline{\cD}} = \cR_i\circ\eta_i\circ(\cR_i|_{\overline{\mathfrak{D}}_i})^{-1}$,
    \end{enumerate}
    for $i\in\{1, 2\}$. Then, there exists a biholomorphism $M: \Sigma_1 \rightarrow\Sigma_2$, such that $\eta_2\circ M = M\circ \eta_1$, $M(\mathfrak{D}_1) = \mathfrak{D}_2$, and $\cR_1 = \cR_2\circ M$.
\end{prop}
\begin{proof}
    Set $\Sigma_i^0:= \Sigma\setminus(\cR_i|_{\partial\mathfrak{D}_i})^{-1}(X)$, $i\in\{1,2\}$, where $X$ is the set of singular points on $\partial\cD$. Define $M:\Sigma_1^0\rightarrow\Sigma_2$ as follows,
    \begin{equation*}
        M(z):= \begin{cases*}
        \big(\cR_2\big|_{\mathfrak{\overline{\mathfrak{D}}_2}}\big)^{-1}\circ \cR_1(z), & if $z\in \Sigma_1^0\cap\overline{\mathfrak{D}}_1$,\\
        \eta_2\circ\big(\cR_2\big|_{\mathfrak{\overline{\mathfrak{D}}_2}}\big)^{-1}\circ \cR_1\circ\eta_1, &if $z\in \Sigma_1^0\setminus\overline{\mathfrak{D}}_1$.
        \end{cases*}
    \end{equation*}
    Note that the function $\big(\cR_2|_{\mathfrak{\partial\mathfrak{D}_2}}\big)^{-1}\circ \cR_1(z)$ conjugates $\eta_1|_{\partial\mathfrak{D}_1\cap\Sigma_1^0}$ to $\eta_2|_{\partial\mathfrak{D}_2\cap\Sigma_2^0}$. Therefore, $M$ is continuous on $\Sigma_1^0$ and conformal away from $\Sigma_1^0\cap\partial\mathfrak{D}_1$. Further, $\Sigma_1^0\cap\partial\mathfrak{D}_1$ is a disjoint union of non-singular analytic curves, and is hence conformally removable. Therefore, $M$ is an injective holomorphic map on $\Sigma_1^0$. Finally, by the Riemann Removability Theorem, $M$ extends to $\Sigma_1$ univalently. From the definition of $M$, it now follows that $\eta_2\circ M = M\circ \eta_1$, $M(\mathfrak{D}_1) = \mathfrak{D}_2$, and $\cR_1 = \cR_2\circ M$.  
\end{proof}

\begin{cor}\label{equiv_limit_sets_cor}
    The map $\widetilde{\varphi}$ conjugates the action of $\mathfrak{C}$ on $\Lambda(\mathfrak{C})$ to the action of $\mathfrak{C}'$ on $\Lambda(\mathfrak{C}')$.
\end{cor}
\begin{proof}
   We continue to use the notation introduced in Proposition~\ref{qc_lift_prop}. Also recall from Section~\ref{inv_partition_corr_subsec} that $\Lambda(\mathfrak{C})=\cR^{-1}(\partial\cK)$ and $\Lambda(\mathfrak{C}')=(\cR')^{-1}(\partial\cK')$, where $\cK, \cK'$ are the non-escaping sets of $S, S'$, respectively. 

   Note that since $\phi$ is a conjugacy between $S$ and $S'$ away from $\bigcup_{j=1}^r\cV_j$, it carries $\partial\cK$ onto $\partial\cK'$. This fact, and the definition of the quasi-regular map $\widecheck{\cR}$, together show that $\widecheck{\cR}^{-1}(\partial\cK')=\Lambda(\mathfrak{C})$. 
   Taking the relation $\cR'\equiv \widecheck{\cR}\circ\widetilde{\phi}^{-1}$ into consideration, we now have that
   $$
   \Lambda(\mathfrak{C}')= (\cR')^{-1}(\partial\cK')=\widetilde{\phi}\left(\widecheck{\cR}^{-1}(\partial\cK')\right)=\widetilde{\phi}(\Lambda(\mathfrak{C})).
   $$
   Finally, as $\cR'=\phi\circ\cR\circ\widetilde{\phi}^{-1}$ on $\widetilde{\phi}(\Lambda(\mathfrak{C}))=\Lambda(\mathfrak{C}')$, and $\widetilde{\phi}\circ\eta=\eta'\circ\widetilde{\phi}$, the following conjugacy relation holds between the local branches of $\mathfrak{C}\vert_{\Lambda(\mathfrak{C})}$ and $\mathfrak{C}'\vert_{\Lambda(\mathfrak{C}')}$:
   \begin{align*}
\widetilde{\phi}\circ\left(\cR^{-1}\circ\cR\circ\eta\right)\circ\widetilde{\phi}^{-1}&=(\widetilde{\phi}\circ\cR^{-1}\circ\phi^{-1})\circ(\phi\circ\cR\circ\widetilde{\phi}^{-1})\circ(\widetilde{\phi}\circ\eta\circ\widetilde{\phi}^{-1})\\
&=(\cR')^{-1}\circ\cR'\circ\eta'.
   \end{align*}
\end{proof}

\subsection{Unification of Teichm\"uller spaces and Blaschke spaces in Hurwitz spaces}\label{para_unif_subsec}

From the discussions in Sections~\ref{limit_sets_equiv_subsec},~\ref{equivalence_of_corr_subsec} and~\ref{injectivity_subsec}, it follows that the parameter space for correspondences $\mathfrak{C}$ combining the dynamics of groups $\{\widehat{\Gamma}_i\}_{i=1}^l$ and maps $\{B_j\}_{j=1}^r$ is $\mathscr{C} = \mathfrak{B}(\mathcal{M})$, and we have,
$$
\mathscr{C} \cong \left(\text{Teich}(\D/\widehat{\Gamma}_1)\times\cdots\times\text{Teich}(\D/\widehat{\Gamma}_l)\right)\times\left(\mathcal{B}_{d_1}\times\cdots\times\mathcal{B}_{d_r}\right).
$$
We are now in a position to complete the proof of Theorem~\ref{hurwitz_thm_intro}, thus concluding the second main component of the narrative of this paper. 
\begin{proof}[Proof of Theorem~\ref{hurwitz_thm_intro}]
    The maps $\mathfrak{B}$, $\mathfrak{B}'$, constructed in Sections~\ref{equivalence_of_corr_subsec} and~\ref{injectivity_subsec}, show the existence of an injective map from $\mathcal{M}$ into the Hurwitz space $\mathcal{H}_{g, d, q}^{\text{hyp}}$. 
\end{proof}

\begin{remark}
    Recall that in Example~\ref{111_ex}, each parameter $t \in \text{Teich}(\Gamma^2_{1,4})\times \mathcal{B}_2$ gives rise to a marked tuple $(\Sigma_t, \cR_t)$, where $\Sigma_t$ is an elliptic curve, and $\cR_t:\Sigma_t\rightarrow\widehat{\C}$ is a degree $4$ elliptic function with $6$ simple critical points and a double critical point. Therefore, by Theorem~\ref{hurwitz_thm_intro}, we get an injective map from $\text{Teich}(\Gamma^2_{1,4})\times \mathcal{B}_2$ into the Hurwitz space $\mathcal{H}_{1, 4, 11}^{\text{hyp}}$.
\end{remark}

